window.AUTH=window.AUTH||{};window.AUTH["23-334"]={"d":"23-334","id":"2023/23-334","n":"Department of State v. Munoz","briefs":[{"k":"petitioner","label":"Brief of petitioners Department of State, et al.","date":"2024-02-20","url":"https://www.supremecourt.gov/DocketPDF/23/23-334/300976/20240220181935001_23-334tsUnitedStates.pdf","side":"pet","n":109},{"k":"respondent","label":"Brief of respondents Sandra Muñoz, et al.","date":"2024-03-21","url":"https://www.supremecourt.gov/DocketPDF/23/23-334/305620/20240321140013833_Merit%20Br.%20for%20Respondents.pdf","side":"res","n":140},{"k":"reply","label":"Reply of petitioners Department of State, et al.","date":"2024-04-12","url":"https://www.supremecourt.gov/DocketPDF/23/23-334/307437/20240412110926112_23-334rbUnitedStates.pdf","side":"pet","n":54}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/602us1r46_gfbi.pdf","tr":true,"items":[{"t":"case","label":"Agency for Int’l Dev. v. Alliance for Open Soc’y Int’l, Inc.","cite":"140 S. Ct. 2082","y":2020,"id":"2019/19-177","sc":1,"sum":"The Court held that a law conditioning federal funding to foreign affiliates of an American organization on those organizations' express policies on prostitution and sex trafficking does not violate the First Amendment because foreign corporations operating outside of the United States do not have First Amendment rights.","sumSrc":"Oyez","by":{"0":"25","1":"29"}},{"t":"case","label":"Agosto v. INS","cite":"436 U.S. 748","y":1978,"id":"1977/76-1410","sc":1,"sum":"The Immigration and Naturalization Service brought proceedings to deport petitioner as an alien who had unlawfully entered the United States. At a series of hearings before an Immigration Judge, the INS presented documentary evidence that petitioner was born in Italy in 1927 of unknown parents, was placed in a foundling home there, and ultimately was adopted by an Italian couple. Petitioner and several other …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Baaghil v. Miller","cite":"1 F.4th 427","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/1/427/","op":3,"sum":"Noting that “[w]hen the Supreme Court itself applies Marks, it is not bound in the same way that lower courts are”.","sumSrc":"brief:0","by":{"0":"20, 26, 31","2":"4, 16"}},{"t":"case","label":"Bakran v. Secretary, United States Dep’t of Homeland Sec.","cite":"894 F.3d 557","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/894/557/","op":1,"by":{"0":"26"}},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"sum":"The Court held that in determining eligibility for cancellation of removal of a lawful permanent resident who commits a serious crime, an offense listed in 8 U.S.C. § 1182(a)(2) committed during the initial seven years of residence need not be one of the offenses of removal.","sumSrc":"Oyez","by":{"0":"2"}},{"t":"case","label":"Bright v. Parra","cite":"919 F.2d 31","y":1990,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/919/31/","op":2,"by":{"0":"26"}},{"t":"case","label":"Brownell v. Tom We Shung","cite":"352 U.S. 180","y":1956,"id":"1956/43","sc":1,"sum":"Under § 10 of the Administrative Procedure Act, an alien whose exclusion has been ordered administratively under the Immigration and Nationality Act of 1952, and who neither claims citizenship nor holds a certificate of identity issued under § 360 (b) of that Act, may obtain judicial review of such order by an action in a federal district court for a declaratory judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16","1":"15","2":"5"}},{"t":"case","label":"Burrafato v. United States Dep’t of State","cite":"523 F.2d 554","y":1975,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/523/554/","op":2,"by":{"0":"26"}},{"t":"case","label":"Bustamante v. Mukasey","cite":"531 F.3d 1059","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/531/1059/","by":{"0":"10, 21"}},{"t":"case","label":"CIA v. Sims","cite":"471 U.S. 159","y":1985,"id":"1984/83-1075","sc":1,"sum":"Between 1953 and 1966, the Central Intelligence Agency (CIA) financed a research project, code-named MKULTRA, that was established to counter Soviet and Chinese advances in brainwashing and interrogation techniques. Subprojects were contracted out to various universities, research foundations, and similar institutions. In 1977, respondents in No. 83-1075 (hereafter respondents) filed a request with the CIA under the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Clapper v. Amnesty Int’l USA","cite":"568 U.S. 398","y":2013,"id":"2012/11-1025","sc":1,"sum":"The Court held that the respondents lacked Article III standing against FISA because fear of intercepted communication and costs incurred to avoid intercepted communications are not injuries.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Cleveland Bd. of Educ. v. LaFleur","cite":"414 U.S. 632","y":1974,"id":"1973/72-777","sc":1,"sum":"The Court held that the school boards' regulations requiring pregnant teachers to stop working after the fifth month of their pregnancies violated the Fourteenth Amendment's due process clause.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Colindres v. United States Dep’t of State","cite":"71 F.4th 1018","y":2023,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/71/1018/","op":3,"sum":"Noting that “[w]hen the Supreme Court itself applies Marks, it is not bound in the same way that lower courts are”.","sumSrc":"brief:0","by":{"0":"26, 35","1":"51"}},{"t":"case","label":"DHS v. Thuraissigiam","cite":"140 S. Ct. 1959","y":2020,"id":"2019/19-161","sc":1,"op":2,"sum":"The Court held that 8 U.S.C. § 1252(e)(2) as applied to the respondent Thuraissigiam does not violate the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"17, 24","1":"16"}},{"t":"case","label":"Del Valle v. Secretary of State","cite":"16 F.4th 832","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/16/832/","op":1,"by":{"0":"26"}},{"t":"case","label":"Din v. Kerry","cite":"718 F.3d 856","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/718/856/","by":{"0":"6, 40"}},{"t":"case","label":"District Attorney’s Office for the Third Judicial Dist. v. Osborne","cite":"557 U.S. 52","y":2009,"id":"2008/08-6","sc":1,"sum":"The Court found that the defendant had no constitutional right to obtain post-conviction access to DNA evidence used against him at trial.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Fiallo v. Bell","cite":"430 U.S. 787","y":1977,"id":"1976/75-6297","sc":1,"op":4,"ar":1,"sum":"Sections 101 (b) (1) (D) and 101 (b) (2) of the Immigration and Nationality Act of 1952, which have the effect of excluding the relationship between an illegitimate child and his natural father (as opposed to his natural mother) from the special preference immigration status accorded by the Act to the \"child\" or \"parent\" of a United States citizen or lawful permanent resident, held not to be unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 25, 40","1":"39, 41","2":"6"}},{"t":"case","label":"Freeman v. United States","cite":"564 U.S. 522","y":2011,"id":"2010/09-10245","sc":1,"sum":"The Court held that a federal judge has the authority to reduce a criminal sentence after the U.S. Sentencing Commission amended the Sentencing Guidelines if the judge has already accepted a plea agreement.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Galvan v. Press","cite":"347 U.S. 522","y":1954,"id":"scdb/1953-075","sc":1,"op":1,"sum":"1. Section 22 of the Internal Security Act of 1950, providing for the deportation of any alien who has been a member of the Communist Party at any time after entry, is constitutional-as here applied to a resident alien shown to have been willingly a member of the Communist Party from 1944 to 1946 although not shown to have been aware of its advocacy of violent overthrow of the Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 24","2":"8"}},{"t":"case","label":"Gundy v. United States","cite":"139 S. Ct. 2116","y":2019,"id":"2018/17-6086","sc":1,"sum":"The Second Circuit’s judgment that 34 U. S. C. §20913(d)—which requires the Attorney General to apply the Sex Offender Registration and Notification Act’s registration requirements as soon as feasible to offenders convicted before the statute’s enactment—is not an unconstitutional delegation of legislative authority is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36"}},{"t":"case","label":"Harisiades v. Shaughnessy","cite":"342 U.S. 580","y":1952,"id":"scdb/1951-056","sc":1,"op":1,"sum":"Observing that “any policy toward aliens is vitally and intricately interwoven with contemporaneous policies in regard to the conduct of foreign relations, the war power, and the maintenance of a republican form of government”.","sumSrc":"brief:0","by":{"0":"17, 25","1":"16"}},{"t":"case","label":"Hughes v. United States","cite":"584 U.S. 675","y":2018,"id":"2017/17-155","sc":1,"sum":"The Court decided that a sentence imposed pursuant to a Federal Rule of Criminal Procedure 11(c)(1)(C) (“Type C”) plea bargain is “based on” the defendant’s Federal Sentencing Guidelines range as long as that range was a component of the framework the court used in imposing the sentence or accepting the plea bargain, meaning that in this case, Erik Hughes could seek a sentencing reduction under 18 U.S.C. § 3582(c)(2).","sumSrc":"Oyez","by":{"0":"34","1":"50"}},{"t":"case","label":"Kerry v. Din","cite":"576 U.S. 88","y":2015,"id":"2014/13-1402","sc":1,"op":11,"sum":"Observing that this argument posits “two categories of implied rights protected by the Due Process Clause: really fundamental rights, which cannot be taken away at all absent a compelling state interest; and not-so-fundamental rights, which can be taken away so long as procedural due process is observed”.","sumSrc":"opinion","by":{"0":"5-7, 14, 15, 27, 28, 31-37, 39, 40, 45, 46","1":"9, 14, 22, 23, 29, 38, 46, 49-51","2":"2, 3, 10-12, 15-17, 19, 20"}},{"t":"case","label":"Kleindienst v. Mandel","cite":"408 U.S. 753","y":1972,"id":"1971/71-16","sc":1,"op":10,"sum":"The Court held that the First Amendment did not obligate Kleindienst to grant a waiver to Mandel.","sumSrc":"Oyez","by":{"0":"4, 5, 13, 14, 16, 17, 20, 31-34","1":"14, 20, 37-42, 47-49, 51, 52","2":"1, 3, 5, 15, 17"}},{"t":"case","label":"Landon v. Plasencia","cite":"459 U.S. 21","y":1982,"id":"1982/81-129","sc":1,"op":1,"sum":"Section 235 of the Immigration and Nationality Act of 1952 (Act) permits the Immigration and Naturalization Service (INS) to examine \"all aliens\" who seek \"admission or readmission to\" the United States and empowers immigration officers to take evidence concerning the privilege of any persons suspected of being an alien \"to enter, reenter, pass through, or reside\" in the United States, and to detain for further …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18","1":"14, 21"}},{"t":"case","label":"Lehr v. Robertson","cite":"463 U.S. 248","y":1983,"id":"1982/81-1756","sc":1,"sum":"The Supreme Court held that due process and equal protection were not violated because Lehr never had a significant personal or financial relationship with Jessica M. Justice Byron R. White dissented, arguing that the state cannot deny notice of adoption proceedings to a biological father when the state knows his whereabouts and interest in the child.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Marks v. United States","cite":"430 U.S. 188","y":1977,"id":"1976/75-708","sc":1,"op":2,"sum":"The Due Process Clause of the Fifth Amendment precludes retroactive application to petitioners of the Miller standards, to the extent that those standards may impose criminal liability for conduct not punishable under the standards announced in Memoirs v. Massachusetts, 383 U. S. 413. Bouie v. City of Columbia, 378 U. S. 347. Specifically, petitioners are entitled to jury instructions requiring the jury to acquit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"Morales-Izquierdo v. DHS","cite":"600 F.3d 1076","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/600/1076/","by":{"0":"30"}},{"t":"case","label":"National Pork Producers Council v. Ross","cite":"598 U.S. 356","y":2023,"id":"2022/21-468","sc":1,"sum":"The judgment of the Court of Appeals for the Ninth Circuit—affirming the dismissal of a complaint challenging California’s Proposition 12 under a dormant Commerce Clause rationale not grounded in an allegation that the law purposefully discriminates against out-of-state economic interests—is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36"}},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"sum":"The Ninth Circuit’s judgments—that respondents, who are deportable for certain specified crimes, are not subject to 8 U. S. C. §1226(c)(2)’s mandatory-detention requirement because they were not arrested by immigration officials as soon as they were released from jail—are reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"2"}},{"t":"case","label":"Nishimura Ekiu v. United States","cite":"142 U.S. 651","y":1892,"id":"scdb/1891-092","sc":1,"op":1,"sum":"The act of March 3, 1891, c. 551, forbidding certain classes of alien immigrants to land in the United States, is constitutional and valid.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"17, 24","1":"16"}},{"t":"case","label":"O’Bannon v. Town Court Nursing Ctr.","cite":"447 U.S. 773","y":1980,"id":"1979/78-1318","sc":1,"op":3,"sum":"The patients have no interest in receiving benefits for care in a particular facility that entitles them, as a matter of constitutional law, to a hearing before HEW and DPW can decertify that facility. Whatever legal rights the patients may have against the nursing home for failing to maintain its status as a qualified nursing home, the enforcement by HEW and DPW of their valid regulations did not directly affect …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14, 28-30","1":"30-34","2":"12, 13"}},{"t":"case","label":"Obergefell v. Hodges","cite":"576 U.S. 644","y":2015,"id":"2014/14-556","sc":1,"op":12,"ar":1,"sum":"Observing that this argument posits “two categories of implied rights protected by the Due Process Clause: really fundamental rights, which cannot be taken away at all absent a compelling state interest; and not-so-fundamental rights, which can be taken away so long as procedural due process is observed”.","sumSrc":"opinion","by":{"0":"10, 26, 27","1":"19"}},{"t":"case","label":"Oceanic Steam Navigation Co. v. Stranahan","cite":"214 U.S. 320","y":1909,"id":"scdb/1908-176","sc":1,"op":1,"sum":"Explaining that “over no conceivable subject is the legislative power of Congress more complete”.","sumSrc":"opinion","by":{"0":"17","1":"16"}},{"t":"case","label":"Pak v. Biden","cite":"91 F.4th 896","y":2024,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/91/896/","by":{"0":"31, 37"}},{"t":"case","label":"Payne-Barahona v. Gonzáles","cite":"474 F.3d 1","y":2007,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/474/1/","by":{"0":"30","2":"13"}},{"t":"case","label":"Saavedra Bruno v. Albright","cite":"197 F.3d 1153","y":1999,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/197/1153/","sum":"Concluding that once the U.S. sponsors’ own “petition was granted,” their “cognizable interest” under the INA “terminated”.","sumSrc":"brief:0","by":{"0":"4, 23","1":"17","2":"4, 5"}},{"t":"case","label":"Scialabba v. Cuellar de Osorio","cite":"573 U.S. 41","y":2014,"id":"2013/12-930","sc":1,"op":1,"sum":"The Court held that the Immigration and Nationality Act does not allow children who have submitted an application for a visa to keep their original application date if they \"aged out\" before it was processed.","sumSrc":"Oyez","by":{"0":"2, 3, 22"}},{"t":"case","label":"Sesay v. United States","cite":"984 F.3d 312","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/984/312/","op":1,"by":{"0":"26"}},{"t":"case","label":"Shaughnessy v. United States ex rel. Mezei","cite":"345 U.S. 206","y":1953,"id":"scdb/1952-067","sc":1,"sum":"The Attorney General's continued exclusion of the alien without a hearing does not amount to an unlpvful detention, and courts may not temporarily admit him to the iJnited States pending arrangements for his departure abroad.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18","1":"16"}},{"t":"case","label":"Silverman v. Rogers","cite":"437 F.2d 102","y":1970,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/437/102/","op":2,"by":{"0":"26"}},{"t":"case","label":"Swartz v. Rogers","cite":"254 F.2d 338","y":1958,"url":"https://www.courtlistener.com/c/F.2d/254/338/","by":{"0":"26"}},{"t":"case","label":"Town of Castle Rock v. Gonzales","cite":"545 U.S. 748","y":2005,"id":"2004/04-278","sc":1,"op":2,"ar":1,"sum":"The Court ruled that Gonzales had no constitutionally-protected property interest in the enforcement of the restraining order, and therefore could not claim that the police had violated her right to due process.","sumSrc":"Oyez","by":{"0":"28","2":"6, 13"}},{"t":"case","label":"Trump v. Hawaii","cite":"585 U.S. 667","y":2018,"id":"2017/17-965","sc":1,"op":5,"ar":13,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"0":"5, 15, 16, 19, 31-33, 37","1":"13, 14, 39, 50","2":"5, 16-18"}},{"t":"case","label":"United States v. Chemical Found.","cite":"272 U.S. 1","y":1926,"id":"scdb/1926-001","sc":1,"sum":"1. A decree of the Circuit Court of Appeals, entered prior to the taking effect of the Jurisdictional Act of February 13, 1925, and affirming dismissal on the merits of a bill by the United States to set aside, as unauthorized and fraudulently procured, sales of patent and other rights and properties seized pursuant to the Trading, with the Enemy Act, was reviewable by this Court on appeal (Jud. Code §§ 128, 241). …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"United States v. Curtiss-Wright Exp. Corp.","cite":"299 U.S. 304","y":1936,"id":"1900-1940/299us304","sc":1,"sum":"The Court held that the President has greater legislative power in international affairs than would be allowed in domestic ones.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"United States v. Duvall","cite":"740 F.3d 604","y":2013,"court":"D.C. Cir","url":"https://www.courtlistener.com/c/F.3d/740/604/","by":{"0":"34"}},{"t":"case","label":"United States ex rel. Knauff v. Shaughnessy","cite":"338 U.S. 537","y":1950,"id":"scdb/1949-033","sc":1,"op":20,"sum":"This action was authorized by the Act of June 21, 1941, 22 U. S. C. § 223, and the proclamations and regulations issued thereunder, notwithstanding the War Brides Act of December 28, 1945, 8 U. S. C. § 232 et seq.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 12, 13, 17, 25","1":"16","2":"3"}},{"t":"case","label":"United States ex rel. London v. Phelps","cite":"22 F.2d 288","y":1927,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/22/288/","by":{"0":"16"}},{"t":"case","label":"United States ex rel. Ulrich v. Kellogg","cite":"30 F.2d 984","y":1929,"url":"https://www.courtlistener.com/c/F.2d/30/984/","op":1,"by":{"0":"16"}},{"t":"case","label":"United States v. Hernandez-Villanueva","cite":"473 F.3d 118","y":2007,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/473/118/","by":{"0":"8"}},{"t":"case","label":"Washington v. Glucksberg","cite":"521 U.S. 702","y":1997,"id":"1996/96-110","sc":1,"op":5,"ar":3,"sum":"The Court decided that a law banning physician-assisted suicide does not violate the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Wilkinson v. Austin","cite":"545 U.S. 209","y":2005,"id":"2004/04-495","sc":1,"op":1,"sum":"The Court held that the procedures by which the New Policy classified prisoners for placement at the facility provided sufficient protection to comply with the due process clause. The Court reasoned that procedural protections afforded to prisoners were necessarily limited, and that the New Policy sufficiently minimized risk of erroneous placement.","sumSrc":"Oyez","by":{"0":"13, 21, 23","1":"42, 44","2":"5"}},{"t":"case","label":"Wong Wing v. United States","cite":"163 U.S. 228","y":1896,"id":"1850-1900/163us228","sc":1,"op":1,"sum":"Consequently, the imprisonment provisions of the Act are void.","sumSrc":"Oyez","by":{"0":"18, 24","1":"16","2":"3"}},{"t":"case","label":"Yafai v. Pompeo","cite":"912 F.3d 1018","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/912/1018/","op":1,"by":{"0":"26","2":"2, 16"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"582 U.S. 120","y":2017,"id":"2016/15-1358","sc":1,"sum":"The Court determined that, in suits against government officials for personally violating the Constitution, “context” should be defined narrowly for the purpose of determining whether a claim arose in a “new context,” and the government officials in this case are entitled to qualified immunity.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"const","label":"Amendment V, Section 5","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"19"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"38"}},{"t":"law","label":"Pub. L. No. 101-649","url":"https://www.govinfo.gov/link/statute/104/5083","by":{"0":"41"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(3)","(a)(9)","(a)(16)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"2, 2, 3, 3","2":"3"}},{"t":"usc","label":"8 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/8/1104","subs":["(a)(1)"],"stext":{"head":"§1104. Powers and duties of Secretary of State","paras":[[0,"(a) Powers and duties"],[0,"The Secretary of State shall be charged with the administration and the enforcement of the provisions of this chapter and all other immigration and nationality laws relating to (1) the powers, duties, and functions of diplomatic and consular officers of the United States, except those powers, duties, and functions conferred upon the consular officers relating to the granting or refusal of visas; (2) the powers, duties, and functions of the Administrator; and (3) the determination of nationality of a person not in the United States. He shall establish such regulations; prescribe such forms of reports, entries and other papers; issue such instructions; and perform such other acts as he deems necessary for carrying out such provisions. He is authorized to confer or impose upon any employee of the United States, with the consent of the head of the department or independent establishment under whose jurisdiction the employee is serving, any of the powers, functions, or duties conferred or imposed by this chapter or regulations issued thereunder upon officers or employees of the Department of State or of the American Foreign Service."],[0,"(b) Designation and duties of Administrator"],[0,"The Secretary of State shall designate an Administrator who shall be a citizen of the United States, qualified by experience. The Administrator shall maintain close liaison with the appropriate committees of Congress in order that they may be advised regarding the administration of this chapter by consular officers. The Administrator shall be charged with any and all responsibility and authority in the administration of this chapter which are conferred on the Secretary of State as may be delegated to the Administrator by the Secretary of State or which may be prescribed by the Secretary of State, and shall perform such other duties as the Secretary of State may prescribe."],[0,"(c) Passport Office, Visa Office, and other offices; directors"],[0,"Within the Department of State there shall be a Passport Office, a Visa Office, and such other offices as the Secretary of State may deem to be appropriate, each office to be headed by a director. The Directors of the Passport Office and the Visa Office shall be experienced in the administration of the nationality and immigration laws."],[0,"(d) Transfer of duties"],[0,"The functions heretofore performed by the Passport Division and the Visa Division of the Department of State shall hereafter be performed by the Passport Office and the Visa Office, respectively."],[0,"(e) General Counsel of Visa Office; appointment and duties"],[0,"There shall be a General Counsel of the Visa Office, who shall be appointed by the Secretary of State and who shall serve under the general direction of the Legal Adviser of the Department of State. The General Counsel shall have authority to maintain liaison with the appropriate officers of the Service with a view to securing uniform interpretations of the provisions of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1104?type=usc&year=mostrecent&link-type=html"},"head":"§1104. Powers and duties of Secretary of State","tname":"Aliens and Nationality","by":{"0":"5","1":"17"}},{"t":"usc","label":"8 U.S.C. § 1105","url":"https://www.law.cornell.edu/uscode/text/8/1105","subs":["(a)"],"by":{"0":"43"}},{"t":"usc","label":"8 U.S.C. § 1151","url":"https://www.law.cornell.edu/uscode/text/8/1151","subs":["(b)(2)(A)(1)","(d)","(b)(2)(A)(i)","(c)"],"stext":{"head":"§1151. Worldwide level of immigration","paras":[[0,"(a) In general"],[0,"Exclusive of aliens described in subsection (b), aliens born in a foreign state or dependent area who may be issued immigrant visas or who may otherwise acquire the status of an alien lawfully admitted to the United States for permanent residence are limited to—"],[1,"(1) family-sponsored immigrants described in section 1153(a) of this title (or who are admitted under section 1181(a) of this title on the basis of a prior issuance of a visa to their accompanying parent under section 1153(a) of this title) in a number not to exceed in any fiscal year the number specified in subsection (c) for that year, and not to exceed in any of the first 3 quarters of any fiscal year 27 percent of the worldwide level under such subsection for all of such fiscal year;"],[1,"(2) employment-based immigrants described in section 1153(b) of this title (or who are admitted under section 1181(a) of this title on the basis of a prior issuance of a visa to their accompanying parent under section 1153(b) of this title), in a number not to exceed in any fiscal year the number specified in subsection (d) for that year, and not to exceed in any of the first 3 quarters of any fiscal year 27 percent of the worldwide level under such subsection for all of such fiscal year; and"],[1,"(3) for fiscal years beginning with fiscal year 1995, diversity immigrants described in section 1153(c) of this title (or who are admitted under section 1181(a) of this title on the basis of a prior issuance of a visa to their accompanying parent under section 1153(c) of this title) in a number not to exceed in any fiscal year the number specified in subsection (e) for that year, and not to exceed in any of the first 3 quarters of any fiscal year 27 percent of the worldwide level under such subsection for all of such fiscal year."],[0,"(b) Aliens not subject to direct numerical limitations"],[0,"Aliens described in this subsection, who are not subject to the worldwide levels or numerical limitations of subsection (a), are as follows:"],[1,"(1)(A) Special immigrants described in subparagraph (A) or (B) of section 1101(a)(27) of this title."],[1,"(B) Aliens who are admitted under section 1157 of this title or whose status is adjusted under section 1159 of this title."],[1,"(C) Aliens whose status is adjusted to permanent residence under section 1160 or 1255a of this title."],[1,"(D) Aliens whose removal is canceled under section 1229b(a) of this title."],[1,"(E) Aliens provided permanent resident status under section 1259 of this title."],[1,"(2)(A)(i) Immediate relatives.—For purposes of this subsection, the term \"immediate relatives\" means the children, spouses, and parents of a citizen of the United States, except that, in the case of parents, such citizens shall be at least 21 years of age. In the case of an alien who was the spouse of a citizen of the United States and was not legally separated from the citizen at the time of the citizen's death, the alien (and each child of the alien) shall be considered, for purposes of this subsection, to remain an immediate relative after the date of the citizen's death but only if the spouse files a petition under section 1154(a)(1)(A)(ii) of this title within 2 years after such date and only until the date the spouse remarries. For purposes of this clause, an alien who has filed a petition under clause (iii) or (iv) of section 1154(a)(1)(A) of this title remains an immediate relative in the event that the United States citizen spouse or parent loses United States citizenship on account of the abuse."],[1,"(ii) Aliens admitted under section 1181(a) of this title on the basis of a prior issuance of a visa to their accompanying parent who is such an immediate relative."],[1,"(B) Aliens born to an alien lawfully admitted for permanent residence during a temporary visit abroad."],[0,"(c) Worldwide level of family-sponsored immigrants"],[0,"(1)(A) The worldwide level of family-sponsored immigrants under this subsection for a fiscal year is, subject to subparagraph (B), equal to—"],[1,"(i) 480,000, minus"],[1,"(ii) the sum of the number computed under paragraph (2) and the number computed under paragraph (4), plus"],[1,"(iii) the number (if any) computed under paragraph (3)."],[0,"(B)(i) For each of fiscal years 1992, 1993, and 1994, 465,000 shall be substituted for 480,000 in subparagraph (A)(i)."],[0,"(ii) In no case shall the number computed under subparagraph (A) be less than 226,000."],[0,"(2) The number computed under this paragraph for a fiscal year is the sum of the number of aliens described in subparagraphs (A) and (B) of subsection (b)(2) who were issued immigrant visas or who otherwise acquired the status of aliens lawfully admitted to the United States for permanent residence in the previous fiscal year."],[0,"(3)(A) The number computed under this paragraph for fiscal year 1992 is zero."],[0,"(B) The number computed under this paragraph for fiscal year 1993 is the difference (if any) between the worldwide level established under paragraph (1) for the previous fiscal year and the number of visas issued under section 1153(a) of this title during that fiscal year."],[0,"(C) The number computed under this paragraph for a subsequent fiscal year is the difference (if any) between the maximum number of visas which may be issued under section 1153(b) of this title (relating to employment-based immigrants) during the previous fiscal year and the number of visas issued under that section during that year."],[0,"(4) The number computed under this paragraph for a fiscal year (beginning with fiscal year 1999) is the number of aliens who were paroled into the United States under section 1182(d)(5) of this title in the second preceding fiscal year—"],[1,"(A) who did not depart from the United States (without advance parole) within 365 days; and"],[1,"(B) who (i) did not acquire the status of aliens lawfully admitted to the United States for permanent residence in the two preceding fiscal years, or (ii) acquired such status in such years under a provision of law (other than subsection (b)) which exempts such adjustment from the numerical limitation on the worldwide level of immigration under this section."],[0,"(5) If any alien described in paragraph (4) (other than an alien described in paragraph (4)(B)(ii)) is subsequently admitted as an alien lawfully admitted for permanent residence, such alien shall not again be considered for purposes of paragraph (1)."],[0,"(d) Worldwide level of employment-based immigrants"],[0,"(1) The worldwide level of employment-based immigrants under this subsection for a fiscal year is equal to—"],[1,"(A) 140,000, plus"],[1,"(B) the number computed under paragraph (2)."],[0,"(2)(A) The number computed under this paragraph for fiscal year 1992 is zero."],[0,"(B) The number computed under this paragraph for fiscal year 1993 is the difference (if any) between the worldwide level established under paragraph (1) for the previous fiscal year and the number of visas issued under section 1153(b) of this title during that fiscal year."],[0,"(C) The number computed under this paragraph for a subsequent fiscal year is the difference (if any) between the maximum number of visas which may be issued under section 1153(a) of this title (relating to family-sponsored immigrants) during the previous fiscal year and the number of visas issued under that section during that year."],[0,"(e) Worldwide level of diversity immigrants"],[0,"The worldwide level of diversity immigrants is equal to 55,000 for each fiscal year."],[0,"(f) Rules for determining whether certain aliens are immediate relatives"],[0,"(1) Age on petition filing date"],[1,"Except as provided in paragraphs (2) and (3), for purposes of subsection (b)(2)(A)(i), a determination of whether an alien satisfies the age requirement in the matter preceding subparagraph (A) of section 1101(b)(1) of this title shall be made using the age of the alien on the date on which the petition is filed with the Attorney General under section 1154 of this title to classify the alien as an immediate relative under subsection (b)(2)(A)(i)."],[0,"(2) Age on parent's naturalization date"],[1,"In the case of a petition under section 1154 of this title initially filed for an alien child's classification as a family-sponsored immigrant under section 1153(a)(2)(A) of this title, based on the child's parent being lawfully admitted for permanent residence, if the petition is later converted, due to the naturalization of the parent, to a petition to classify the alien as an immediate relative under subsection (b)(2)(A)(i), the determination described in paragraph (1) shall be made using the age of the alien on the date of the parent's naturalization."],[0,"(3) Age on marriage termination date"],[1,"In the case of a petition under section 1154 of this title initially filed for an alien's classification as a family-sponsored immigrant under section 1153(a)(3) of this title, based on the alien's being a married son or daughter of a citizen, if the petition is later converted, due to the legal termination of the alien's marriage, to a petition to classify the alien as an immediate relative under subsection (b)(2)(A)(i) or as an unmarried son or daughter of a citizen under section 1153(a)(1) of this title, the determination described in paragraph (1) shall be made using the age of the alien on the date of the termination of the marriage."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1151?type=usc&year=mostrecent&link-type=html"},"head":"§1151. Worldwide level of immigration","tname":"Aliens and Nationality","by":{"0":"2, 22","1":"25, 25"}},{"t":"usc","label":"8 U.S.C. § 1153","url":"https://www.law.cornell.edu/uscode/text/8/1153","subs":["(b)","(a)(2)"],"stext":{"head":"§1153. Allocation of immigrant visas","paras":[[0,"(a) Preference allocation for family-sponsored immigrants"],[0,"Aliens subject to the worldwide level specified in section 1151(c) of this title for family-sponsored immigrants shall be allotted visas as follows:"],[0,"(1) Unmarried sons and daughters of citizens"],[1,"Qualified immigrants who are the unmarried sons or daughters of citizens of the United States shall be allocated visas in a number not to exceed 23,400, plus any visas not required for the class specified in paragraph (4)."],[0,"(2) Spouses and unmarried sons and unmarried daughters of permanent resident aliens"],[1,"Qualified immigrants—"],[2,"(A) who are the spouses or children of an alien lawfully admitted for permanent residence, or"],[2,"(B) who are the unmarried sons or unmarried daughters (but are not the children) of an alien lawfully admitted for permanent residence,"],[1,"shall be allocated visas in a number not to exceed 114,200, plus the number (if any) by which such worldwide level exceeds 226,000, plus any visas not required for the class specified in paragraph (1); except that not less than 77 percent of such visa numbers shall be allocated to aliens described in subparagraph (A)."],[0,"(3) Married sons and married daughters of citizens"],[1,"Qualified immigrants who are the married sons or married daughters of citizens of the United States shall be allocated visas in a number not to exceed 23,400, plus any visas not required for the classes specified in paragraphs (1) and (2)."],[0,"(4) Brothers and sisters of citizens"],[1,"Qualified immigrants who are the brothers or sisters of citizens of the United States, if such citizens are at least 21 years of age, shall be allocated visas in a number not to exceed 65,000, plus any visas not required for the classes specified in paragraphs (1) through (3)."],[0,"(b) Preference allocation for employment-based immigrants"],[0,"Aliens subject to the worldwide level specified in section 1151(d) of this title for employment-based immigrants in a fiscal year shall be allotted visas as follows:"],[0,"(1) Priority workers"],[1,"Visas shall first be made available in a number not to exceed 28.6 percent of such worldwide level, plus any visas not required for the classes specified in paragraphs (4) and (5), to qualified immigrants who are aliens described in any of the following subparagraphs (A) through (C):"],[0,"(A) Aliens with extraordinary ability"],[2,"An alien is described in this subparagraph if—"],[3,"(i) the alien has extraordinary ability in the sciences, arts, education, business, or athletics which has been demonstrated by sustained national or international acclaim and whose achievements have been recognized in the field through extensive documentation,"],[3,"(ii) the alien seeks to enter the United States to continue work in the area of extraordinary ability, and"],[3,"(iii) the alien's entry into the United States will substantially benefit prospectively the United States."],[0,"(B) Outstanding professors and researchers"],[2,"An alien is described in this subparagraph if—"],[3,"(i) the alien is recognized internationally as outstanding in a specific academic area,"],[3,"(ii) the alien has at least 3 years of experience in teaching or research in the academic area, and"],[3,"(iii) the alien seeks to enter the United States—"],[4,"(I) for a tenured position (or tenure-track position) within a university or institution of higher education to teach in the academic area,"],[4,"(II) for a comparable position with a university or institution of higher education to conduct research in the area, or"],[4,"(III) for a comparable position to conduct research in the area with a department, division, or institute of a private employer, if the department, division, or institute employs at least 3 persons full-time in research activities and has achieved documented accomplishments in an academic field."],[0,"(C) Certain multinational executives and managers"],[2,"An alien is described in this subparagraph if the alien, in the 3 years preceding the time of the alien's application for classification and admission into the United States under this subparagraph, has been employed for at least 1 year by a firm or corporation or other legal entity or an affiliate or subsidiary thereof and the alien seeks to enter the United States in order to continue to render services to the same employer or to a subsidiary or affiliate thereof in a capacity that is managerial or executive."],[0,"(2) Aliens who are members of the professions holding advanced degrees or aliens of exceptional ability"],[0,"(A) In general"],[2,"Visas shall be made available, in a number not to exceed 28.6 percent of such worldwide level, plus any visas not required for the classes specified in paragraph (1), to qualified immigrants who are members of the professions holding advanced degrees or their equivalent or who because of their exceptional ability in the sciences, arts, or business, will substantially benefit prospectively the national economy, cultural or educational interests, or welfare of the United States, and whose services in the sciences, arts, professions, or business are sought by an employer in the United States."],[0,"(B) Waiver of job offer"],[0,"(i) National interest waiver"],[3,"Subject to clause (ii), the Attorney General may, when the Attorney General deems it to be in the national interest, waive the requirements of subparagraph (A) that an alien's services in the sciences, arts, professions, or business be sought by an employer in the United States."],[0,"(ii) Physicians working in shortage areas or veterans facilities"],[0,"(I) In general"],[4,"The Attorney General shall grant a national interest waiver pursuant to clause (i) on behalf of any alien physician with respect to whom a petition for preference classification has been filed under subparagraph (A) if—"],[5,"(aa) the alien physician agrees to work full time as a physician in an area or areas designated by the Secretary of Health and Human Services as having a shortage of health care professionals or at a health care facility under the jurisdiction of the Secretary of Veterans Affairs; and"],[5,"(bb) a Federal agency or a department of public health in any State has previously determined that the alien physician's work in such an area or at such facility was in the public interest."],[0,"(II) Prohibition"],[4,"No permanent resident visa may be issued to an alien physician described in subclause (I) by the Secretary of State under section 1154(b) of this title, and the Attorney General may not adjust the status of such an alien physician from that of a nonimmigrant alien to that of a permanent resident alien under section 1255 of this title, until such time as the alien has worked full time as a physician for an aggregate of 5 years (not including the time served in the status of an alien described in section 1101(a)(15)(J) of this title), in an area or areas designated by the Secretary of Health and Human Services as having a shortage of health care professionals or at a health care facility under the jurisdiction of the Secretary of Veterans Affairs."],[0,"(III) Statutory construction"],[4,"Nothing in this subparagraph may be construed to prevent the filing of a petition with the Attorney General for classification under section 1154(a) of this title, or the filing of an application for adjustment of status under section 1255 of this title, by an alien physician described in subclause (I) prior to the date by which such alien physician has completed the service described in subclause (II)."],[0,"(IV) Effective date"],[4,"The requirements of this subsection do not affect waivers on behalf of alien physicians approved under subsection (b)(2)(B) before the enactment date of this subsection. In the case of a physician for whom an application for a waiver was filed under subsection (b)(2)(B) prior to November 1, 1998, the Attorney General shall grant a national interest waiver pursuant to subsection (b)(2)(B) except that the alien is required to have worked full time as a physician for an aggregate of 3 years (not including time served in the status of an alien described in section 1101(a)(15)(J) of this title) before a visa can be issued to the alien under section 1154(b) of this title or the status of the alien is adjusted to permanent resident under section 1255 of this title."],[0,"(C) Determination of exceptional ability"],[2,"In determining under subparagraph (A) whether an immigrant has exceptional ability, the possession of a degree, diploma, certificate, or similar award from a college, university, school, or other institution of learning or a license to practice or certification for a particular profession or occupation shall not by itself be considered sufficient evidence of such exceptional ability."],[0,"(3) Skilled workers, professionals, and other workers"],[0,"(A) In general"],[2,"Visas shall be made available, in a number not to exceed 28.6 percent of such worldwide level, plus any visas not required for the classes specified in paragraphs (1) and (2), to the following classes of aliens who are not described in paragraph (2):"],[0,"(i) Skilled workers"],[3,"Qualified immigrants who are capable, at the time of petitioning for classification under this paragraph, of performing skilled labor (requiring at least 2 years training or experience), not of a temporary or seasonal nature, for which qualified workers are not available in the United States."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1153?type=usc&year=mostrecent&link-type=html"},"head":"§1153. Allocation of immigrant visas","tname":"Aliens and Nationality","by":{"0":"22","2":"14"}},{"t":"usc","label":"8 U.S.C. § 1154","url":"https://www.law.cornell.edu/uscode/text/8/1154","subs":["(a)","(a)(1)","(a)(1)(A)","(b)","(a)(1)(A)(i)"],"stext":{"head":"§1154. Procedure for granting immigrant status","paras":[[0,"(a) Petitioning procedure"],[0,"(1)(A)(i) Except as provided in clause (viii), any citizen of the United States claiming that an alien is entitled to classification by reason of a relationship described in paragraph (1), (3), or (4) of section 1153(a) of this title or to an immediate relative status under section 1151(b)(2)(A)(i) of this title may file a petition with the Attorney General for such classification."],[0,"(ii) An alien spouse described in the second sentence of section 1151(b)(2)(A)(i) of this title also may file a petition with the Attorney General under this subparagraph for classification of the alien (and the alien's children) under such section."],[0,"(iii)(I) An alien who is described in subclause (II) may file a petition with the Attorney General under this clause for classification of the alien (and any child of the alien) if the alien demonstrates to the Attorney General that—"],[1,"(aa) the marriage or the intent to marry the United States citizen was entered into in good faith by the alien; and"],[1,"(bb) during the marriage or relationship intended by the alien to be legally a marriage, the alien or a child of the alien has been battered or has been the subject of extreme cruelty perpetrated by the alien's spouse or intended spouse."],[0,"(II) For purposes of subclause (I), an alien described in this subclause is an alien—"],[1,"(aa)(AA) who is the spouse of a citizen of the United States;"],[1,"(BB) who believed that he or she had married a citizen of the United States and with whom a marriage ceremony was actually performed and who otherwise meets any applicable requirements under this chapter to establish the existence of and bona fides of a marriage, but whose marriage is not legitimate solely because of the bigamy of such citizen of the United States; or"],[1,"(CC) who was a bona fide spouse of a United States citizen within the past 2 years and—"],[2,"(aaa) whose spouse died within the past 2 years;"],[2,"(bbb) whose spouse lost or renounced citizenship status within the past 2 years related to an incident of domestic violence; or"],[2,"(ccc) who demonstrates a connection between the legal termination of the marriage within the past 2 years and battering or extreme cruelty by the United States citizen spouse;"],[1,"(bb) who is a person of good moral character;"],[1,"(cc) who is eligible to be classified as an immediate relative under section 1151(b)(2)(A)(i) of this title or who would have been so classified but for the bigamy of the citizen of the United States that the alien intended to marry; and"],[1,"(dd) who has resided with the alien's spouse or intended spouse."],[0,"(iv) An alien who is the child of a citizen of the United States, or who was a child of a United States citizen parent who within the past 2 years lost or renounced citizenship status related to an incident of domestic violence, and who is a person of good moral character, who is eligible to be classified as an immediate relative under section 1151(b)(2)(A)(i) of this title, and who resides, or has resided in the past, with the citizen parent may file a petition with the Attorney General under this subparagraph for classification of the alien (and any child of the alien) under such section if the alien demonstrates to the Attorney General that the alien has been battered by or has been the subject of extreme cruelty perpetrated by the alien's citizen parent. For purposes of this clause, residence includes any period of visitation."],[0,"(v) An alien who—"],[1,"(I) is the spouse, intended spouse, or child living abroad of a citizen who—"],[2,"(aa) is an employee of the United States Government;"],[2,"(bb) is a member of the uniformed services (as defined in section 101(a) of title 10); or"],[2,"(cc) has subjected the alien or the alien's child to battery or extreme cruelty in the United States; and"],[1,"(II) is eligible to file a petition under clause (iii) or (iv),"],[0,"shall file such petition with the Attorney General under the procedures that apply to self-petitioners under clause (iii) or (iv), as applicable."],[0,"(vi) For the purposes of any petition filed under clause (iii) or (iv), the denaturalization, loss or renunciation of citizenship, death of the abuser, divorce, or changes to the abuser's citizenship status after filing of the petition shall not adversely affect the approval of the petition, and for approved petitions shall not preclude the classification of the eligible self-petitioning spouse or child as an immediate relative or affect the alien's ability to adjust status under subsections (a) and (c) of section 1255 of this title or obtain status as a lawful permanent resident based on the approved self-petition under such clauses."],[0,"(vii) An alien may file a petition with the Secretary of Homeland Security under this subparagraph for classification of the alien under section 1151(b)(2)(A)(i) of this title if the alien—"],[1,"(I) is the parent of a citizen of the United States or was a parent of a citizen of the United States who, within the past 2 years, lost or renounced citizenship status related to an incident of domestic violence or died;"],[1,"(II) is a person of good moral character;"],[1,"(III) is eligible to be classified as an immediate relative under section 1151(b)(2)(A)(i) of this title;"],[1,"(IV) resides, or has resided, with the citizen daughter or son; and"],[1,"(V) demonstrates that the alien has been battered or subject to extreme cruelty by the citizen daughter or son."],[0,"(viii)(I) Clause (i) shall not apply to a citizen of the United States who has been convicted of a specified offense against a minor, unless the Secretary of Homeland Security, in the Secretary's sole and unreviewable discretion, determines that the citizen poses no risk to the alien with respect to whom a petition described in clause (i) is filed."],[0,"(II) For purposes of subclause (I), the term \"specified offense against a minor\" is defined as in section 20911 of title 34."],[0,"(B)(i)(I) Except as provided in subclause (II), any alien lawfully admitted for permanent residence claiming that an alien is entitled to a classification by reason of the relationship described in section 1153(a)(2) of this title may file a petition with the Attorney General for such classification."],[0,"(I) 1 Subclause (I) shall not apply in the case of an alien lawfully admitted for permanent residence who has been convicted of a specified offense against a minor (as defined in subparagraph (A)(viii)(II)), unless the Secretary of Homeland Security, in the Secretary's sole and unreviewable discretion, determines that such person poses no risk to the alien with respect to whom a petition described in subclause (I) is filed."],[0,"(ii)(I) An alien who is described in subclause (II) may file a petition with the Attorney General under this clause for classification of the alien (and any child of the alien) if such a child has not been classified under clause (iii) of section 1153(a)(2)(A) of this title and if the alien demonstrates to the Attorney General that—"],[1,"(aa) the marriage or the intent to marry the lawful permanent resident was entered into in good faith by the alien; and"],[1,"(bb) during the marriage or relationship intended by the alien to be legally a marriage, the alien or a child of the alien has been battered or has been the subject of extreme cruelty perpetrated by the alien's spouse or intended spouse."],[0,"(II) For purposes of subclause (I), an alien described in this paragraph is an alien—"],[1,"(aa)(AA) who is the spouse of a lawful permanent resident of the United States; or"],[1,"(BB) who believed that he or she had married a lawful permanent resident of the United States and with whom a marriage ceremony was actually performed and who otherwise meets any applicable requirements under this chapter to establish the existence of and bona fides of a marriage, but whose marriage is not legitimate solely because of the bigamy of such lawful permanent resident of the United States; or"],[1,"(CC) who was a bona fide spouse of a lawful permanent resident within the past 2 years and—"],[2,"(aaa) whose spouse lost status within the past 2 years due to an incident of domestic violence; or"],[2,"(bbb) who demonstrates a connection between the legal termination of the marriage within the past 2 years and battering or extreme cruelty by the lawful permanent resident spouse;"],[1,"(bb) who is a person of good moral character;"],[1,"(cc) who is eligible to be classified as a spouse of an alien lawfully admitted for permanent residence under section 1153(a)(2)(A) of this title or who would have been so classified but for the bigamy of the lawful permanent resident of the United States that the alien intended to marry; and"],[1,"(dd) who has resided with the alien's spouse or intended spouse."],[0,"(iii) An alien who is the child of an alien lawfully admitted for permanent residence, or who was the child of a lawful permanent resident who within the past 2 years lost lawful permanent resident status due to an incident of domestic violence, and who is a person of good moral character, who is eligible for classification under section 1153(a)(2)(A) of this title, and who resides, or has resided in the past, with the alien's permanent resident alien parent may file a petition with the Attorney General under this subparagraph for classification of the alien (and any child of the alien) under such section if the alien demonstrates to the Attorney General that the alien has been battered by or has been the subject of extreme cruelty perpetrated by the alien's permanent resident parent."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1154?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1154. Procedure for granting immigrant status","tname":"Aliens and Nationality","by":{"0":"22, 21, 2, 3, 22","1":"3"}},{"t":"usc","label":"8 U.S.C. § 1181","url":"https://www.law.cornell.edu/uscode/text/8/1181","subs":["(a)"],"stext":{"head":"§1181. Admission of immigrants into the United States","paras":[[0,"(a) Documents required; admission under quotas before June 30, 1968"],[0,"Except as provided in subsection (b) and subsection (c) no immigrant shall be admitted into the United States unless at the time of application for admission he (1) has a valid unexpired immigrant visa or was born subsequent to the issuance of such visa of the accompanying parent, and (2) presents a valid unexpired passport or other suitable travel document, or document of identity and nationality, if such document is required under the regulations issued by the Attorney General. With respect to immigrants to be admitted under quotas of quota areas prior to June 30, 1968, no immigrant visa shall be deemed valid unless the immigrant is properly chargeable to the quota area under the quota of which the visa is issued."],[0,"(b) Readmission without required documents; Attorney General's discretion"],[0,"Notwithstanding the provisions of section 1182(a)(7)(A) of this title in such cases or in such classes of cases and under such conditions as may be by regulations prescribed, returning resident immigrants, defined in section 1101(a)(27)(A) of this title, who are otherwise admissible may be readmitted to the United States by the Attorney General in his discretion without being required to obtain a passport, immigrant visa, reentry permit or other documentation."],[0,"(c) Nonapplicability to aliens admitted as refugees"],[0,"The provisions of subsection (a) shall not apply to an alien whom the Attorney General admits to the United States under section 1157 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1181?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1181. Admission of immigrants into the United States","tname":"Aliens and Nationality","by":{"0":"2"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)","(a)(2)","(a)(3)","(a)(3)(A)(i)","(a)(3)(A)(ii)","(a)(3)(B)","(a)(3)(B)(i)(II)","(a)(7)","(b)","(b)(1)","(b)(3)","(a)(2)(D)","(a)(2)(I)(i)","(a)(3)(A)","(a)(9)(B)(v)","(a)(3)(B)(i)(IV)(bb)","(a)(3)(B)(i)(VIII)","(a)(3)(B)(iii)(I)","(a)(3)(B)(iv)(VI)(cc)","(a)(3)(B)(iv)(VI)(dd)","(a)(9)(B)(i)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§1182. Inadmissible aliens","tname":"Aliens and Nationality","by":{"0":"3, 47, 2, 22, 37, 4, 38, 40, 3, 4, 33, 38, 40, 41, 4, 4, 7, 9, 10, 12, 14, 29, 31, 32, 35, 39, 41, 42, 35, 35, 2, 4, 4, 4, 15, 31","1":"6, 46, 47, 48, 48, 6, 46, 47, 48, 6, 26, 1, 7-9, 11, 17, 37, 41, 43-49, 50-52, 9, 50, 51, 4, 16, 27, 31, 29, 38, 46","2":"6, 20, 1, 15, 17-19, 17-19, 18, 18, 18, 18, 19, 7, 7, 20, 19, 20"}},{"t":"usc","label":"8 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/8/1201","subs":["(a)","(a)(1)","(d)","(g)","(i)","(a)(1)(A)"],"stext":{"head":"§1201. Issuance of visas","paras":[[0,"(a) Immigrants; nonimmigrants"],[0,"(1) Under the conditions hereinafter prescribed and subject to the limitations prescribed in this chapter or regulations issued thereunder, a consular officer may issue"],[1,"(A) to an immigrant who has made proper application therefor, an immigrant visa which shall consist of the application provided for in section 1202 of this title, visaed by such consular officer, and shall specify the foreign state, if any, to which the immigrant is charged, the immigrant's particular status under such foreign state, the preference, immediate relative, or special immigrant classification to which the alien is charged, the date on which the validity of the visa shall expire, and such additional information as may be required; and"],[1,"(B) to a nonimmigrant who has made proper application therefor, a nonimmigrant visa, which shall specify the classification under section 1101(a)(15) of this title of the nonimmigrant, the period during which the nonimmigrant visa shall be valid, and such additional information as may be required."],[0,"(2) The Secretary of State shall provide to the Service an electronic version of the visa file of each alien who has been issued a visa to ensure that the data in that visa file is available to immigration inspectors at the United States ports of entry before the arrival of the alien at such a port of entry."],[0,"(b) Registration; photographs; waiver of requirement"],[0,"Each alien who applies for a visa shall be registered in connection with his application, and shall furnish copies of his photograph signed by him for such use as may be by regulations required. The requirements of this subsection may be waived in the discretion of the Secretary of State in the case of any alien who is within that class of nonimmigrants enumerated in sections 1101(a)(15)(A), and 1101(a)(15)(G) of this title, or in the case of any alien who is granted a diplomatic visa on a diplomatic passport or on the equivalent thereof."],[0,"(c) Period of validity; renewal or replacement"],[0,"(1) Immigrant visas"],[1,"An immigrant visa shall be valid for such period, not exceeding six months, as shall be by regulations prescribed, except that any visa issued to a child lawfully adopted by a United States citizen and spouse while such citizen is serving abroad in the United States Armed Forces, or is employed abroad by the United States Government, or is temporarily abroad on business, shall be valid until such time, for a period not to exceed three years, as the adoptive citizen parent returns to the United States in due course of his service, employment, or business."],[0,"(2) Nonimmigrant visas"],[1,"A nonimmigrant visa shall be valid for such periods as shall be by regulations prescribed. In prescribing the period of validity of a nonimmigrant visa in the case of nationals of any foreign country who are eligible for such visas, the Secretary of State shall, insofar as practicable, accord to such nationals the same treatment upon a reciprocal basis as such foreign country accords to nationals of the United States who are within a similar class; except that in the case of aliens who are nationals of a foreign country and who either are granted refugee status and firmly resettled in another foreign country or are granted permanent residence and residing in another foreign country, the Secretary of State may prescribe the period of validity of such a visa based upon the treatment granted by that other foreign country to alien refugees and permanent residents, respectively, in the United States."],[0,"(3) Visa replacement"],[1,"An immigrant visa may be replaced under the original number during the fiscal year in which the original visa was issued for an immigrant who establishes to the satisfaction of the consular officer that the immigrant—"],[2,"(A) was unable to use the original immigrant visa during the period of its validity because of reasons beyond his control and for which he was not responsible;"],[2,"(B) is found by a consular officer to be eligible for an immigrant visa; and"],[2,"(C) pays again the statutory fees for an application and an immigrant visa."],[0,"(4) Fee waiver"],[1,"If an immigrant visa was issued, on or after March 27, 2013, for a child who has been lawfully adopted, or who is coming to the United States to be adopted, by a United States citizen, any statutory immigrant visa fees relating to a renewal or replacement of such visa may be waived or, if already paid, may be refunded upon request, subject to such criteria as the Secretary of State may prescribe, if—"],[2,"(A) the immigrant child was unable to use the original immigrant visa during the period of its validity as a direct result of extraordinary circumstances, including the denial of an exit permit; and"],[2,"(B) if such inability was attributable to factors beyond the control of the adopting parent or parents and of the immigrant."],[0,"(d) Physical examination"],[0,"Prior to the issuance of an immigrant visa to any alien, the consular officer shall require such alien to submit to a physical and mental examination in accordance with such regulations as may be prescribed. Prior to the issuance of a nonimmigrant visa to any alien, the consular officer may require such alien to submit to a physical or mental examination, or both, if in his opinion such examination is necessary to ascertain whether such alien is eligible to receive a visa."],[0,"(e) Surrender of visa"],[0,"Each immigrant shall surrender his immigrant visa to the immigration officer at the port of entry, who shall endorse on the visa the date and the port of arrival, the identity of the vessel or other means of transportation by which the immigrant arrived, and such other endorsements as may be by regulations required."],[0,"(f) Surrender of documents"],[0,"Each nonimmigrant shall present or surrender to the immigration officer at the port of entry such documents as may be by regulation required. In the case of an alien crewman not in possession of any individual documents other than a passport and until such time as it becomes practicable to issue individual documents, such alien crewman may be admitted, subject to the provisions of this part, if his name appears in the crew list of the vessel or aircraft on which he arrives and the crew list is visaed by a consular officer, but the consular officer shall have the right to deny admission to any alien crewman from the crew list visa."],[0,"(g) Nonissuance of visas or other documents"],[0,"No visa or other documentation shall be issued to an alien if (1) it appears to the consular officer, from statements in the application, or in the papers submitted therewith, that such alien is ineligible to receive a visa or such other documentation under section 1182 of this title, or any other provision of law, (2) the application fails to comply with the provisions of this chapter, or the regulations issued thereunder, or (3) the consular officer knows or has reason to believe that such alien is ineligible to receive a visa or such other documentation under section 1182 of this title, or any other provision of law: Provided, That a visa or other documentation may be issued to an alien who is within the purview of section 1182(a)(4) of this title, if such alien is otherwise entitled to receive a visa or other documentation, upon receipt of notice by the consular officer from the Attorney General of the giving of a bond or undertaking providing indemnity as in the case of aliens admitted under section 1183 of this title: Provided further, That a visa may be issued to an alien defined in section 1101(a)(15)(B) or (F) of this title, if such alien is otherwise entitled to receive a visa, upon receipt of a notice by the consular officer from the Attorney General of the giving of a bond with sufficient surety in such sum and containing such conditions as the consular officer shall prescribe, to insure that at the expiration of the time for which such alien has been admitted by the Attorney General, as provided in section 1184(a) of this title, or upon failure to maintain the status under which he was admitted, or to maintain any status subsequently acquired under section 1258 of this title, such alien will depart from the United States."],[0,"(h) Nonadmission upon arrival"],[0,"Nothing in this chapter shall be construed to entitle any alien, to whom a visa or other documentation has been issued, to be admitted 1 the United States, if, upon arrival at a port of entry in the United States, he is found to be inadmissible under this chapter, or any other provision of law. The substance of this subsection shall appear upon every visa application."],[0,"(i) Revocation of visas or documents"],[0,"After the issuance of a visa or other documentation to any alien, the consular officer or the Secretary of State may at any time, in his discretion, revoke such visa or other documentation. Notice of such revocation shall be communicated to the Attorney General, and such revocation shall invalidate the visa or other documentation from the date of issuance: Provided, That carriers or transportation companies, and masters, commanding officers, agents, owners, charterers, or consignees, shall not be penalized under section 1323(b) of this title for action taken in reliance on such visas or other documentation, unless they received due notice of such revocation prior to the alien's embarkation. There shall be no means of judicial review (including review pursuant to section 2241 of title 28 or any other habeas corpus provision, and sections 1361 and 1651 of such title) of a revocation under this subsection, except in the context of a removal proceeding if such revocation provides the sole ground for removal under section 1227(a)(1)(B) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1201?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1201. Issuance of visas","tname":"Aliens and Nationality","by":{"0":"22, 22, 22, 19, 19","1":"3, 26, 40","2":"6, 7, 3"}},{"t":"usc","label":"8 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/8/1202","subs":["(a)","(b)","(e)"],"by":{"0":"3, 7, 22, 22, 7, 22, 44"}},{"t":"usc","label":"8 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/8/1225","subs":["(c)(1)"],"by":{"0":"30"}},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","by":{"0":"30"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1252. Judicial review of orders of removal","tname":"Aliens and Nationality","by":{"0":"5","1":"16","2":"3"}},{"t":"usc","label":"8 U.S.C. § 1361","url":"https://www.law.cornell.edu/uscode/text/8/1361","stext":{"head":"§1361. Burden of proof upon alien","paras":[[0,"Whenever any person makes application for a visa or any other document required for entry, or makes application for admission, or otherwise attempts to enter the United States, the burden of proof shall be upon such person to establish that he is eligible to receive such visa or such document, or is not inadmissible under any provision of this chapter, and, if an alien, that he is entitled to the nonimmigrant, immigrant, special immigrant, immediate relative, or refugee status claimed, as the case may be. If such person fails to establish to the satisfaction of the consular officer that he is eligible to receive a visa or other document required for entry, no visa or other document required for entry shall be issued to such person, nor shall such person be admitted to the United States unless he establishes to the satisfaction of the Attorney General that he is not inadmissible under any provision of this chapter. In any removal proceeding under part IV of this subchapter against any person, the burden of proof shall be upon such person to show the time, place, and manner of his entry into the United States, but in presenting such proof he shall be entitled to the production of his visa or other entry document, if any, and of any other documents and records, not considered by the Attorney General to be confidential, pertaining to such entry in the custody of the Service. If such burden of proof is not sustained, such person shall be presumed to be in the United States in violation of law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1361?type=usc&year=mostrecent&link-type=html"},"head":"§1361. Burden of proof upon alien","tname":"Aliens and Nationality","by":{"0":"44","2":"7"}},{"t":"usc","label":"8 U.S.C. § 1733","url":"https://www.law.cornell.edu/uscode/text/8/1733","by":{"0":"44"}},{"t":"usc","label":"6 U.S.C. § 236","url":"https://www.law.cornell.edu/uscode/text/6/236","subs":["(b)(1)","(c)(1)","(f)"],"stext":{"head":"§236. Visa issuance","paras":[[0,"(a) Definition"],[0,"In this subsection,1 the term \"consular office\" 2 has the meaning given that term under section 101(a)(9) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(9))."],[0,"(b) In general"],[0,"Notwithstanding section 104(a) of the Immigration and Nationality Act (8 U.S.C. 1104(a)) or any other provision of law, and except as provided in subsection (c) of this section, the Secretary—"],[1,"(1) shall be vested exclusively with all authorities to issue regulations with respect to, administer, and enforce the provisions of such Act [8 U.S.C. 1101 et seq.], and of all other immigration and nationality laws, relating to the functions of consular officers of the United States in connection with the granting or refusal of visas, and shall have the authority to refuse visas in accordance with law and to develop programs of homeland security training for consular officers (in addition to consular training provided by the Secretary of State), which authorities shall be exercised through the Secretary of State, except that the Secretary shall not have authority to alter or reverse the decision of a consular officer to refuse a visa to an alien; and"],[1,"(2) shall have authority to confer or impose upon any officer or employee of the United States, with the consent of the head of the executive agency under whose jurisdiction such officer or employee is serving, any of the functions specified in paragraph (1)."],[0,"(c) Authority of the Secretary of State"],[0,"(1) In general"],[1,"Notwithstanding subsection (b), the Secretary of State may direct a consular officer to refuse a visa to an alien if the Secretary of State deems such refusal necessary or advisable in the foreign policy or security interests of the United States."],[0,"(2) Construction regarding authority"],[1,"Nothing in this section, consistent with the Secretary of Homeland Security's authority to refuse visas in accordance with law, shall be construed as affecting the authorities of the Secretary of State under the following provisions of law:"],[2,"(A) Section 101(a)(15)(A) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(15)(A))."],[2,"(B) Section 204(d)(2) of the Immigration and Nationality Act (8 U.S.C. 1154) (as it will take effect upon the entry into force of the Convention on Protection of Children and Cooperation in Respect to Inter-Country adoption)."],[2,"(C) Section 212(a)(3)(B)(i)(IV)(bb) of the Immigration and Nationality Act (8 U.S.C. 1182(a)(3)(B)(i)(IV)(bb))."],[2,"(D) Section 212(a)(3)(B)(i)(VI) of the Immigration and Nationality Act (8 U.S.C. 1182(a)(3)(B)(i)(VI))."],[2,"(E) Section 212(a)(3)(B)(vi)(II) of the Immigration and Nationality Act (8 U.S.C. 1182(a)(3)(B)(vi)(II))."],[2,"(F) Section 212(a)(3)(C) of the Immigration and Nationality Act (8 U.S.C. 1182(a)(3)(C))."],[2,"(G) Section 212(a)(10)(C) of the Immigration and Nationality Act (8 U.S.C. 1182(a)(10)(C))."],[2,"(H) Section 212(f) of the Immigration and Nationality Act (8 U.S.C. 1182(f))."],[2,"(I) Section 219(a) of the Immigration and Nationality Act (8 U.S.C. 1189(a))."],[2,"(J) Section 237(a)(4)(C) of the Immigration and Nationality Act (8 U.S.C. 1227(a)(4)(C))."],[2,"(K) Section 401 of the Cuban Liberty and Democratic Solidarity (LIBERTAD) Act of 1996 [22 U.S.C. 6091]."],[2,"(L) Section 613 of the Departments of Commerce, Justice, and State, the Judiciary and Related Agencies Appropriations Act, 1999 3 (as contained in section 101(b) of division A of Public Law 105–277) (Omnibus Consolidated and Emergency Supplemental Appropriations Act, 1999); 112 Stat. 2681; H.R. 4328 (originally H.R. 4276) as amended by section 617 of Public Law 106–553."],[2,"(M) Section 103(f) of the Chemical Weapon Convention Implementation Act of 1998 [22 U.S.C. 6713(f)] (112 Stat. 2681–865)."],[2,"(N) Section 801 of H.R. 3427, the Admiral James W. Nance and Meg Donovan Foreign Relations Authorization Act, Fiscal Years 2000 and 2001 [8 U.S.C. 1182e], as enacted by reference in Public Law 106–113."],[2,"(O) Section 568 of the Foreign Operations, Export Financing, and Related Programs Appropriations Act, 2002 (Public Law 107–115)."],[2,"(P) Section 51 of the State Department Basic Authorities Act of 1956 (22 U.S.C. 2723)."],[0,"(d) Consular officers and chiefs of missions"],[0,"(1) In general"],[1,"Nothing in this section may be construed to alter or affect—"],[2,"(A) the employment status of consular officers as employees of the Department of State; or"],[2,"(B) the authority of a chief of mission under section 207 of the Foreign Service Act of 1980 (22 U.S.C. 3927)."],[0,"(2) Construction regarding delegation of authority"],[1,"Nothing in this section shall be construed to affect any delegation of authority to the Secretary of State by the President pursuant to any proclamation issued under section 212(f) of the Immigration and Nationality Act (8 U.S.C. 1182(f)), consistent with the Secretary of Homeland Security's authority to refuse visas in accordance with law."],[0,"(e) Assignment of Homeland Security employees to diplomatic and consular posts"],[0,"(1) In general"],[1,"The Secretary is authorized to assign employees of the Department to each diplomatic and consular post at which visas are issued, unless the Secretary determines that such an assignment at a particular post would not promote homeland security."],[0,"(2) Functions"],[1,"Employees assigned under paragraph (1) shall perform the following functions:"],[2,"(A) Provide expert advice and training to consular officers regarding specific security threats relating to the adjudication of individual visa applications or classes of applications."],[2,"(B) Review any such applications, either on the initiative of the employee of the Department or upon request by a consular officer or other person charged with adjudicating such applications."],[2,"(C) Conduct investigations with respect to consular matters under the jurisdiction of the Secretary."],[0,"(3) Evaluation of consular officers"],[1,"The Secretary of State shall evaluate, in consultation with the Secretary, as deemed appropriate by the Secretary, the performance of consular officers with respect to the processing and adjudication of applications for visas in accordance with performance standards developed by the Secretary for these procedures."],[0,"(4) Report"],[1,"The Secretary shall, on an annual basis, submit a report to Congress that describes the basis for each determination under paragraph (1) that the assignment of an employee of the Department at a particular diplomatic post would not promote homeland security."],[0,"(5) Permanent assignment; participation in terrorist lookout committee"],[1,"When appropriate, employees of the Department assigned to perform functions described in paragraph (2) may be assigned permanently to overseas diplomatic or consular posts with country-specific or regional responsibility. If the Secretary so directs, any such employee, when present at an overseas post, shall participate in the terrorist lookout committee established under section 304 of the Enhanced Border Security and Visa Entry Reform Act of 2002 (8 U.S.C. 1733)."],[0,"(6) Training and hiring"],[0,"(A) In general"],[2,"The Secretary shall ensure, to the extent possible, that any employees of the Department assigned to perform functions under paragraph (2) and, as appropriate, consular officers, shall be provided the necessary training to enable them to carry out such functions, including training in foreign languages, interview techniques, and fraud detection techniques, in conditions in the particular country where each employee is assigned, and in other appropriate areas of study."],[0,"(B) Use of Center"],[2,"The Secretary is authorized to use the National Foreign Affairs Training Center, on a reimbursable basis, to obtain the training described in subparagraph (A)."],[0,"(7) Report"],[1,"Not later than 1 year after November 25, 2002, the Secretary and the Secretary of State shall submit to Congress—"],[2,"(A) a report on the implementation of this subsection; and"],[2,"(B) any legislative proposals necessary to further the objectives of this subsection."],[0,"(8) Effective date"],[1,"This subsection shall take effect on the earlier of—"],[2,"(A) the date on which the President publishes notice in the Federal Register that the President has submitted a report to Congress setting forth a memorandum of understanding between the Secretary and the Secretary of State governing the implementation of this section; or"],[2,"(B) the date occurring 1 year after November 25, 2002."],[0,"(f) No creation of private right of action"],[0,"Nothing in this section shall be construed to create or authorize a private right of action to challenge a decision of a consular officer or other United States official or employee to grant or deny a visa."],[0,"(g) Study regarding use of foreign nationals"],[0,"(1) In general"],[1,"The Secretary of Homeland Security shall conduct a study of the role of foreign nationals in the granting or refusal of visas and other documents authorizing entry of aliens into the United States. The study shall address the following:"],[2,"(A) The proper role, if any, of foreign nationals in the process of rendering decisions on such grants and refusals."],[2,"(B) Any security concerns involving the employment of foreign nationals."],[2,"(C) Whether there are cost-effective alternatives to the use of foreign nationals."],[0,"(2) Report"],[1,"Not later than 1 year after November 25, 2002, the Secretary shall submit a report containing the findings of the study conducted under paragraph (1) to the Committee on the Judiciary, the Committee on International Relations, and the Committee on Government Reform of the House of Representatives, and the Committee on the Judiciary, the Committee on Foreign Relations, and the Committee on Government 4 Affairs of the Senate."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/6/236?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§236. Visa issuance","tname":"Domestic Security","by":{"0":"3, 5, 3, 5","1":"16","2":"4, 4"}},{"t":"usc","label":"6 U.S.C. § 251","url":"https://www.law.cornell.edu/uscode/text/6/251","by":{"0":"2"}},{"t":"usc","label":"6 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/6/271","subs":["(b)"],"stext":{"head":"§271. Establishment of Bureau of Citizenship and Immigration Services","paras":[[0,"(a) Establishment of Bureau"],[0,"(1) In general"],[1,"There shall be in the Department a bureau to be known as the \"Bureau of Citizenship and Immigration Services\"."],[0,"(2) Director"],[1,"The head of the Bureau of Citizenship and Immigration Services shall be the Director of the Bureau of Citizenship and Immigration Services, who—"],[2,"(A) shall report directly to the Deputy Secretary;"],[2,"(B) shall have a minimum of 5 years of management experience; and"],[2,"(C) shall be paid at the same level as the Assistant Secretary of the Bureau of Border Security."],[0,"(3) Functions"],[1,"The Director of the Bureau of Citizenship and Immigration Services—"],[2,"(A) shall establish the policies for performing such functions as are transferred to the Director by this section or this chapter or otherwise vested in the Director by law;"],[2,"(B) shall oversee the administration of such policies;"],[2,"(C) shall advise the Deputy Secretary with respect to any policy or operation of the Bureau of Citizenship and Immigration Services that may affect the Bureau of Border Security of the Department, including potentially conflicting policies or operations;"],[2,"(D) shall establish national immigration services policies and priorities;"],[2,"(E) shall meet regularly with the Ombudsman described in section 272 of this title to correct serious service problems identified by the Ombudsman; and"],[2,"(F) shall establish procedures requiring a formal response to any recommendations submitted in the Ombudsman's annual report to Congress within 3 months after its submission to Congress."],[0,"(4) Managerial rotation program"],[0,"(A) In general"],[2,"Not later than 1 year after the effective date specified in section 455,1 the Director of the Bureau of Citizenship and Immigration Services shall design and implement a managerial rotation program under which employees of such bureau holding positions involving supervisory or managerial responsibility and classified, in accordance with chapter 51 of title 5, as a GS–14 or above, shall—"],[3,"(i) gain some experience in all the major functions performed by such bureau; and"],[3,"(ii) work in at least one field office and one service center of such bureau."],[0,"(B) Report"],[2,"Not later than 2 years after the effective date specified in section 455,1 the Secretary shall submit a report to Congress on the implementation of such program."],[0,"(5) Pilot initiatives for backlog elimination"],[1,"The Director of the Bureau of Citizenship and Immigration Services is authorized to implement innovative pilot initiatives to eliminate any remaining backlog in the processing of immigration benefit applications, and to prevent any backlog in the processing of such applications from recurring, in accordance with section 1573(a) of title 8. Such initiatives may include measures such as increasing personnel, transferring personnel to focus on areas with the largest potential for backlog, and streamlining paperwork."],[0,"(b) Transfer of functions from Commissioner"],[0,"In accordance with subchapter XII (relating to transition provisions), there are transferred from the Commissioner of Immigration and Naturalization to the Director of the Bureau of Citizenship and Immigration Services the following functions, and all personnel, infrastructure, and funding provided to the Commissioner in support of such functions immediately before the effective date specified in section 455: 1"],[1,"(1) Adjudications of immigrant visa petitions."],[1,"(2) Adjudications of naturalization petitions."],[1,"(3) Adjudications of asylum and refugee applications."],[1,"(4) Adjudications performed at service centers."],[1,"(5) All other adjudications performed by the Immigration and Naturalization Service immediately before the effective date specified in section 455.1"],[0,"(c) Chief of Policy and Strategy"],[0,"(1) In general"],[1,"There shall be a position of Chief of Policy and Strategy for the Bureau of Citizenship and Immigration Services."],[0,"(2) Functions"],[1,"In consultation with Bureau of Citizenship and Immigration Services personnel in field offices, the Chief of Policy and Strategy shall be responsible for—"],[2,"(A) making policy recommendations and performing policy research and analysis on immigration services issues; and"],[2,"(B) coordinating immigration policy issues with the Chief of Policy and Strategy for the Bureau of Border Security of the Department."],[0,"(d) Legal advisor"],[0,"(1) In general"],[1,"There shall be a principal legal advisor to the Director of the Bureau of Citizenship and Immigration Services."],[0,"(2) Functions"],[1,"The legal advisor shall be responsible for—"],[2,"(A) providing specialized legal advice, opinions, determinations, regulations, and any other assistance to the Director of the Bureau of Citizenship and Immigration Services with respect to legal matters affecting the Bureau of Citizenship and Immigration Services; and"],[2,"(B) representing the Bureau of Citizenship and Immigration Services in visa petition appeal proceedings before the Executive Office for Immigration Review."],[0,"(e) Budget Officer"],[0,"(1) In general"],[1,"There shall be a Budget Officer for the Bureau of Citizenship and Immigration Services."],[0,"(2) Functions"],[0,"(A) 2 In general"],[2,"The Budget Officer shall be responsible for—"],[3,"(i) formulating and executing the budget of the Bureau of Citizenship and Immigration Services;"],[3,"(ii) financial management of the Bureau of Citizenship and Immigration Services; and"],[3,"(iii) collecting all payments, fines, and other debts for the Bureau of Citizenship and Immigration Services."],[0,"(f) Chief of Office of Citizenship"],[0,"(1) In general"],[1,"There shall be a position of Chief of the Office of Citizenship for the Bureau of Citizenship and Immigration Services."],[0,"(2) Functions"],[1,"The Chief of the Office of Citizenship for the Bureau of Citizenship and Immigration Services shall be responsible for promoting instruction and training on citizenship responsibilities for aliens interested in becoming naturalized citizens of the United States, including the development of educational materials."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/6/271?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§271. Establishment of Bureau of Citizenship and Immigration Services","tname":"Domestic Security","by":{"0":"2"}},{"t":"usc","label":"6 U.S.C. § 542","url":"https://www.law.cornell.edu/uscode/text/6/542","by":{"0":"2"}},{"t":"usc","label":"6 U.S.C. § 557","url":"https://www.law.cornell.edu/uscode/text/6/557","by":{"0":"2"}},{"t":"usc","label":"8 U.S.C. § 1551","url":"https://www.law.cornell.edu/uscode/text/8/1551","by":{"0":"2"}},{"t":"case","label":"Afroyim v. Rusk","cite":"387 U.S. 253","y":1967,"id":"1966/456","sc":1,"sum":"In a 5-to-4 decision, overruling Perez v. Brownell (356 US 44), the Court held that Congress has no general power to revoke American citizenship without consent. Noting the special bond between Americans and their government, a bond that protects every citizen against all manner of destruction of their rights, the Court held that only citizens themselves may voluntarily relinquish their citizenship.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Aptheker v. Sec’y of State","cite":"378 U.S. 500","y":1964,"id":"1963/461","sc":1,"sum":"Appellants, native-born citizens and residents of the United States, are ranking officials of the Communist Party of the United States. After hearings under State Department regulations, appellants' passports were revoked under § 6 of the Subversive Activities Control Act of 1950, which provides that when a Communist organization is registered, or under final order to register, it shall be unlawful for any member …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"18"}},{"t":"case","label":"Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Barry v. Barchi","cite":"443 U.S. 55","y":1979,"id":"1978/77-803","sc":1,"sum":"The New York State Racing and Wagering Board (Board), which is empowered to license horse trainers participating in harness horse-race meets in New York, has issued regulations specifying the standards of conduct that a trainer must satisfy to retain his license. The trainer's responsibility rules provide that when a postrace test of a horse reveals the presence of drugs, it is to be presumed-subject to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Bd. of Regents of State Colleges v. Roth","cite":"408 U.S. 564","y":1972,"id":"1971/71-162","sc":1,"op":8,"sum":"The court held 5-3 that Roth had no protected interest in continued employment, as he had completed his contracted term, and therefore was no Fourteenth Amendment protection.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Bell v. Burson","cite":"402 U.S. 535","y":1971,"id":"1970/5586","sc":1,"sum":"Georgia's Motor Vehicle Safety Responsibility Act, which provides that the motor vehicle registration and driver's license of an uninsured motorist involved in an accident shall be suspended unless he posts security for the amount of damages claimed by an aggrieved party and which excludes any consideration of fault or responsibility for the accident at a pre-suspension hearing held violative of procedural due …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26, 27"}},{"t":"case","label":"Blanchard v. Bergeron","cite":"489 U.S. 87","y":1989,"id":"1988/87-1485","sc":1,"sum":"After a jury awarded petitioner $10,000 in damages on his claim that respondent sheriff's deputy had beaten him and thereby deprived him of his civil rights under 42 U. S. C. § 1983, the Federal District Court awarded him $7,500 in attorney's fees under 42 U. S. C. § 1988, which provides that the court, \"in its discretion, may allow... a reasonable attorney's fee\" to a prevailing party in certain federal civil …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"sum":"The Court held that the Military Commissions Act of 2006 violated the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Bowen v. Michigan Academy of Family Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"op":1,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Califano v. Sanders","cite":"430 U.S. 99","y":1977,"id":"1976/75-1443","sc":1,"op":2,"sum":"1. Section 10 of the Administrative Procedure Act (APA), providing generally for judicial review of actions of federal administrative agencies by persons aggrieved by such actions, does not afford an implied grant to district courts of subject-matter jurisdiction to review a decision of the Secretary of Health, Education, and Welfare not to reopen a previously adjudicated claim for social security benefits. An …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Department of the Navy v. Egan","cite":"484 U.S. 518","y":1988,"id":"1987/86-1552","sc":1,"sum":"In an appeal pursuant to § 7513, the Board does not have authority to review the substance of an underlying security-clearance determination in the course of reviewing an adverse action.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Douglas v. Buder","cite":"412 U.S. 430","y":1973,"id":"1972/72-6198","sc":1,"sum":"The issuande of\" the traffic citation was not an 'arrest under either Missouri or Arkansas law, and the finding that petitioner had violated his probation conditions was so totally devoid of evidentiary support as to violate due process. Even were it clear that respondent held Missouri law to be that a traffic citation is the equivalent of an arrest, suchan unforeseeable holding, retroactively applied, would also …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Flemming v. Nestor","cite":"363 U.S. 603","y":1960,"id":"1959/54","sc":1,"sum":"The Court held that the Social Security system was meant to be a form of long-term social insurance that has to constantly adapt to the demands of a changing workforce, which prevents it from fitting within the framework of the right to accrued property.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Frost v. R.R. Comm’n of State of Cal.","cite":"271 U.S. 583","y":1926,"id":"scdb/1925-198","sc":1,"sum":"Mr. Max Thelen, with whom Messrs. H. H. Sanborn, Delancey C. Smith, Frank R. Devlin, Douglas Brook-man, and Edwin C. Blanchard were on the brief, for plaintiffs in error.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"Garrity v. New Jersey","cite":"385 U.S. 493","y":1967,"id":"1966/13","sc":1,"sum":"The Court held that the threat of loss of employment constituted coercion in violation of the Fifth and Fourteenth Amendments.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Gegiow v. Uhl","cite":"239 U.S. 3","y":1915,"id":"scdb/1915-065","sc":1,"sum":"The courts haye jurisdiction to determine whether the reasons given by the Commissioner of Immigration for excluding aliens under the Alien Immigration Act agree with the requirements of the Act; and, if the record shows that the Commissioner exceeded his powers, the alien may obtain his release upon habeas corpus.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Goldberg v. Kelly","cite":"397 U.S. 254","y":1970,"id":"1969/62","sc":1,"sum":"In a 5-to-3 decision, the Court held that states must afford public aid recipients a pre-termination evidentiary hearing before discontinuing their aid.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Goss v. Lopez","cite":"419 U.S. 565","y":1975,"id":"1974/73-898","sc":1,"sum":"The Court ruled that Ohio violated students' Due Process rights guaranteed by the First Amendment when it imposed suspensions without preliminary hearings.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Greenholtz v. Inmates of Neb. Penal & Correctional Complex","cite":"442 U.S. 1","y":1979,"id":"1978/78-201","sc":1,"sum":"The Court held that, although there is no constitutional right to an inmate’s release from prison prior to the expiration of a valid sentence, the specific wording of the Nebraska statute created a constitutionally protected expectation of parole.","sumSrc":"Oyez","by":{"1":"26, 42"}},{"t":"case","label":"Hall v. Hall","cite":"584 U.S. 59","y":2018,"id":"2017/16-1150","sc":1,"sum":"The Court decided that when one of multiple cases consolidated under FRCP 42(a) is finally decided, that ruling confers upon the losing party the right to immediate appeal regardless of whether any of the other consolidated cases are still pending.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Hamdi v. Rumsfeld","cite":"542 U.S. 507","y":2004,"id":"2003/03-6696","sc":1,"sum":"The Court held that individuals held in military confinement by the national government have a right, under the Fifth Amendment, to appeal that confinement in front of a neutral decision-making body.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Izumi Seimitsu Kogyo Kabushiki Kaisha v. U.S. Philips Corp.","cite":"510 U.S. 27","y":1993,"id":"1993/92-1123","sc":1,"sum":"Petitioner Izumi Seimitsu Kogyo Kabushiki Kaisha was a party at the first trial in an action brought against it and respondent Windmere Corporation by respondent U. S. Philips Corporation, but was not a party to the second trial, in which Windmere prevailed. While the judgments from the second trial were on appeal, respondents reached a settlement and filed a joint motion to vacate the District Court's judgments. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"Jay v. Boyd","cite":"351 U.S. 345","y":1956,"id":"1955/503","sc":1,"sum":"The Attorney General has properly exercised his discretionary powers under the statute in this case, and denial of the application is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Ky. Dep’t of Corrections v. Thompson","cite":"490 U.S. 454","y":1989,"id":"1988/87-1815","sc":1,"sum":"The Kentucky regulations do not give state inmates a liberty interest in receiving visitors that is entitled to the protections of the Due Process Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Kwong Hai Chew v. Colding","cite":"344 U.S. 590","y":1953,"id":"scdb/1952-047","sc":1,"sum":"Petitioner's detention, without notice of any charges against him and without opportunity to be' heard in opposition to them, was not authorized by 8 CFR § 175.57 (b). Pp. 600-603. 192 F. 2d 1009., reversed. KWONG HAI CHEW v. COLDING. 590\"'","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"Lem Moon Sing v. United States","cite":"158 U.S. 538","y":1895,"id":"scdb/1894-233","sc":1,"sum":"The power of Congress to.exclude aliens altogether from the United States,, or to prescribe the terms and conditions upon which they may come to-this country, and to have its declared policy in that respect enforced-exclusively through executive officers without judicial intervention, having been settled by previous adjudications, it is now decided that a statute passed in execution of that power is applicable to an …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Logan v. Zimerman Brush Co.","cite":"455 U.S. 422","y":1982,"id":"1981/80-5950","sc":1,"sum":"The judgment is reversed, and the case is remanded. 82 Ill. 2d 99, 411 N. E. 2d 277, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Loving v. Commonwealth","cite":"206 Va. 924","y":1966,"court":"Va.","url":"https://www.courtlistener.com/c/Va./206/924/","by":{"1":"20"}},{"t":"case","label":"Loving v. Virginia","cite":"388 U.S. 1","y":1967,"id":"1966/395","sc":1,"op":2,"sum":"The Court held that the Fourteenth Amendment prohibits governments from discriminating against individuals on the basis of race.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Ludecke v. U.S. Marshal","cite":"15 F.3d 496","y":1994,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/15/496/","by":{"1":"40"}},{"t":"case","label":"Lutwak v. United States","cite":"344 U.S. 604","y":1953,"id":"scdb/1952-048","sc":1,"sum":"Petitioners were convicted of a conspiracy to defraud the United States by obtaining the illegal entry thereto of three aliens as spouses of honorably discharged veterans. They had conspired to have three such veterans journey to Paris, there go through marriage ceremonies with three aliens, bring them to the United States, and obtain their entry under the War Brides Act. The parties to the marriages were not to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Mackenzie v. Hare","cite":"239 U.S. 299","y":1915,"id":"scdb/1915-022","sc":1,"sum":"In construing a statute, whatever was said or given prominence in debate gives way to its actual language as passed; all reasons that induced its enactment and all of its purposes must be supposed to be satisfied and expressed by its words as finally enacted.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"23","2":"10"}},{"t":"case","label":"Marcello v. Bonds","cite":"349 U.S. 302","y":1955,"id":"scdb/1954-086","sc":1,"sum":"After a hearing pursuant to § 242 (b) of the Immigration and Nationality Act of 1952, petitioner, an alien who had been convicted in 1938 of violation of the Marihuana Tax Act, was ordered deported. Section 241 (a) (11) of the 1952 Act makes such conviction at any time ground for deportation, and § 241 (d) provides that the deportation prdvisions of § 241 (a) shall apply even though the facts giving rise to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Match-E-Be-Nash-She-Wish Band of Pottawatomi Indians v. Patchak","cite":"567 U.S. 209","y":2012,"id":"2011/11-246","sc":1,"sum":"The Court held that a neighbor of a proposed Indian casino had standing to sue the government for taking 147 acres of a town's land under Section 465 of the Indian Reorganization Act.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Mathews v. Eldridge","cite":"424 U.S. 319","y":1976,"id":"1975/74-204","sc":1,"ar":3,"sum":"In an 6-to-2 decision, the Court held that the initial termination of Eldridge's benefits without a hearing did not violate due process.","sumSrc":"Oyez","by":{"1":"37, 43","2":"15"}},{"t":"case","label":"Memphis Light, Gas & Water Div. v. Craft","cite":"436 U.S. 1","y":1978,"id":"1977/76-39","sc":1,"sum":"Because of two separate sets of gas and electric meters in their newly purchased house, respondents, for about a year after moving in, received separate monthly bills for each set of meters from a municipal utility. During this period respondents' utility service was terminated five times for nonpayment of bills. Despite respondent wife's good-faith efforts to determine the cause of the \"double billing,\" she was …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25, 26"}},{"t":"case","label":"Meyer v. Nebraska","cite":"262 U.S. 390","y":1923,"id":"1900-1940/262us390","sc":1,"op":3,"ar":2,"sum":"A case in which the Court struck down under the Fourteenth Amendment a Nebraska law prohibiting teachers from instructing grade school children any language other than English.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Michigan v. EPA","cite":"576 U.S. 743","y":2015,"id":"2014/14-46","sc":1,"op":11,"sum":"Observing that this argument posits “two categories of implied rights protected by the Due Process Clause: really fundamental rights, which cannot be taken away at all absent a compelling state interest; and not-so-fundamental rights, which can be taken away so long as procedural due process is observed”.","sumSrc":"opinion","by":{"1":"17"}},{"t":"case","label":"Miller v. Albright","cite":"523 U.S. 420","y":1998,"id":"1997/96-1060","sc":1,"sum":"After ruling that Miller had standing to challenge the constitutionality of a federal statute, the Court held that 8 U.S.C. Section 1409 did not violate the Equal Protection Clause.","sumSrc":"Oyez","by":{"1":"13, 15"}},{"t":"case","label":"Moore v. City of East Cleveland","cite":"431 U.S. 494","y":1977,"id":"1976/75-6289","sc":1,"sum":"The four justices in the plurality held that the ordinance violated Moore's rights as it constituted \"intrusive regulation of the family\" without accruing some tangible state interest. Justice Stevens joined in the judgment and argued that the ordinance was invalid because, by regulating who could live with Moore, it constituted a taking of property without just compensation.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Morfin v. Tillerson","cite":"851 F.3d 710","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/851/710/","by":{"1":"49"}},{"t":"case","label":"Morrissey v. Brewer","cite":"408 U.S. 471","y":1972,"id":"1971/71-5103","sc":1,"op":8,"sum":"The Court held that due process required Iowa to include a preliminary hearing to determine probable cause for the parole revocations of Morrissey and Booker.","sumSrc":"Oyez","by":{"1":"26, 28"}},{"t":"case","label":"Mullane v. Cent. Hanover Bank & Trust Co.","cite":"339 U.S. 306","y":1950,"id":"scdb/1949-066","sc":1,"ar":2,"sum":"A trust company in New York which had exclusive management and control of a common trust fund established by it under § 100-c of the New York Banking Law petitioned under that section for a judicial settlement of accounts which would be binding and conclusive as to any matter set forth therein upon everyone having any interest in the common fund or in any participating trust. In this common fund the trust company …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Olim v. Wakinekona","cite":"461 U.S. 238","y":1983,"id":"1982/81-1581","sc":1,"sum":"Petitioner members of a prison \"Program Committee,\" after investigating a breakdown in discipline and the failure of certain programs within the maximum control unit of the Hawaii State Prison outside Honolulu, singled out respondent and another inmate as troublemakers. After a hearing-respondent having been notified thereof and having retained counsel to represent him-the same Committee recommended that …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Oyama v. California","cite":"332 U.S. 633","y":1948,"id":"scdb/1947-025","sc":1,"sum":"1. The California Alien Land Law, as applied in this case to effect an escheat to the State of certain agricultural lands recorded in the name of a minor, American citizen because they had been paid for by his father, a Japanese alien ineligible for naturalization who was appointed, the son's guardian, held to have deprived the son of the equal protection of the laws and of his privileges as an American citizen, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"Paul v. Davis","cite":"424 U.S. 693","y":1976,"id":"1975/74-891","sc":1,"sum":"In a 5-to-3 decision, the Court held that Davis had not been deprived of any constitutional rights under the Due Process Clause. The Court also emphasized that constitutional privacy interests did not cover Davis's claims.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Perry v. Sindermann","cite":"408 U.S. 593","y":1972,"id":"1971/70-36","sc":1,"op":8,"sum":"The Court affirmed the Fifth Circuit and held that Sindermann was entitled to a full trial in federal District Court and a hearing before the Board of Regents. The Court acknowledged that Sindermann did not have a contractual or tenure-based right to continued employment by Odessa Junior College.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Procunier v. Martinez","cite":"416 U.S. 396","y":1974,"id":"1973/72-1465","sc":1,"op":1,"sum":"The Court held that it was proper for the district court to refuse to abstain from deciding the constitutionality of the regulations. The Court further held that the censorship of direct personal correspondence created incidental restrictions on the right to free speech for both prisoners and their correspondents.","sumSrc":"Oyez","by":{"1":"34, 40","2":"13"}},{"t":"case","label":"Prushinowski v. Samples","cite":"734 F.2d 1016","y":1984,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/734/1016/","by":{"1":"40"}},{"t":"case","label":"Purkett v. Elem","cite":"514 U.S. 765","y":1995,"id":"1994/94-802","sc":1,"sum":"Relying on Batson v. Kentucky, 476 U. S. 79, respondent objected to a prosecutor's use of a peremptory challenge to strike, inter alios, a black male juror from the jury at his robbery trial. The Missouri trial court overruled the objection after the prosecutor explained that he struck the juror because of the juror's long, unkempt hair, his moustache, and his beard. The jury was empaneled, and respondent was …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39"}},{"t":"case","label":"Reno v. Catholic Social Services, Inc.","cite":"509 U.S. 43","y":1993,"id":"1992/91-1826","sc":1,"sum":"The record is insufficient to allow this Court to decide all issues necessary to determine whether the District Courts had jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Ricci v. DeStefano","cite":"557 U.S. 557","y":2009,"id":"2008/07-1428","sc":1,"sum":"The Court held that a municipality violated Title VII of the Civil Rights Act of 1964 when it rejected otherwise valid civil service exams because the results unintentionally prevented the promotion of minority candidates.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Roberts v. U.S. Jaycees","cite":"468 U.S. 609","y":1984,"id":"1983/83-724","sc":1,"sum":"The Court held that the Jaycees chapters lacked \"the distinctive characteristics that might afford constitutional protection to the decision of its members to exclude women.\" The Court reasoned that making women full members would not impose any serious burdens on the male members' freedom of expressive association.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Rocha v. INS","cite":"450 F.2d 946","y":1971,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/450/946/","by":{"1":"23"}},{"t":"case","label":"Rusk v. Cort","cite":"369 U.S. 367","y":1962,"id":"scdb/1961-054","sc":1,"sum":"Appellee was born in the United States but has resided abroad since 1951. His original passport having expired, he applied to the United States Embassy in Prague, Czechoslovakia, for a new one. This was denied on the ground that he had lost his citizenship under § 349 (a) (10) of the Immigration and Nationality Act of 1952 by remaining outside the United States for the purpose of avoiding military service. He sued …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Saenz v. Roe","cite":"526 U.S. 489","y":1999,"id":"1998/98-97","sc":1,"sum":"In a 7-to-2 decision, the Court held that the Fourteenth Amendment protects the right to travel in three ways by: allowing citizens to move freely between states, securing the right to be treated equally in all states when visiting, and securing the rights of new citizens to be treated like long-time citizens of a state.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Sale v. Haitian Centers Council, Inc.","cite":"509 U.S. 155","y":1993,"id":"1992/92-344","sc":1,"sum":"And, it found that both section 243(h) and Article 33 are silent regarding extraterritorial application. In fact, the language of both suggests that only individuals who have already arrived on United States soil are protected, and their use throughout history confirms this interpretation. Thus, the judgment of the Court of Appeals is reversed.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Schware v. Board of Bar Examiners","cite":"353 U.S. 232","y":1957,"id":"1956/92","sc":1,"sum":"On the record in this case, the State of New Mexico deprived petitioner of due process in denying him the opportunity to qualify for the practice of law.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Simmons v. United States","cite":"390 U.S. 377","y":1968,"id":"1967/55","sc":1,"sum":"A federally insured savings and loan association (hereafter \"the bank\") was robbed by two unmasked men. Five bank employees witnessed the robbery, and on the day it occurred gave the FBI written statements. Petitioners, Simmons and Garrett, and another (Andrews) were subsequently indicted for the crime. In the afternoon of the day of the robbery, FBI agents made a warrantless search of Andrews' mother's house and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"Smith v. Goguen","cite":"415 U.S. 566","y":1974,"id":"1973/72-1254","sc":1,"sum":"Appellee, for wearing a small United States flag sewn to the seat of his trousers, was convicted of violating the provision of the Massachusetts flag-misuse statute that subjects to criminal liability anyone who \"publicly.. treats contemptuously' the flag of the United States....\" The Massachusetts. Supreme Judicial Court affirmed. The District Court in appellee's habeas -corpus action found the \"treats …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Smith v. Org. of Foster Families","cite":"431 U.S. 816","y":1977,"id":"1976/76-180","sc":1,"ar":1,"sum":"In this litigation appellees, individual foster parents and a foster parents organzation, sought declaratory and injunctive relief against New York State and New York City officials, alleging that the statutory and regulatory procedures for removal of foster children from foster homes violated the Due Process and Equal Protection Clauses of the Fourteenth Amendment. Under the New York Social Services Law the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19, 21"}},{"t":"case","label":"Superintendent, Mass. Correctional Institution v. Hill","cite":"472 U.S. 445","y":1985,"id":"1984/84-438","sc":1,"sum":"Respondent inmates in a Massachusetts state prison each received disciplinary reports charging them with assaulting another inmate. At separate hearings, a prison disciplinary board heard testimony from a prison guard and received his written report. According to this evidence the guard heard some commotion in a prison walkway and, upon investigating, discovered an inmate who evidently had just been assaulted, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Travers v. Reinhardt","cite":"205 U.S. 423","y":1907,"id":"scdb/1906-110","sc":1,"sum":"While the predominant idea of, the testator’s mind when discovered is to be heeded as against all doubtful and conflicting provisions, which might defeat it, effect must be given to all the words of a will if by the rules of law it can be done; and the words “without leaving a wife or child or children” will not be construed as “without leaving á wife and child or children,” notwithstanding a general dominant, …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Tsoi Sim v. United States","cite":"116 F. 920","y":1902,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F./116/920/","by":{"1":"22"}},{"t":"case","label":"Turner v. Safley","cite":"482 U.S. 78","y":1987,"id":"1986/85-1384","sc":1,"op":4,"sum":"Justice O’Connor further reasoned that the restrictions did not deprive inmates of all means of expression, only limiting correspondence with a particular class of people. She argued that the Eighth Circuit failed to consider the impact easing the restriction might have on the liberty and safety of prison guards and other inmates.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"U.S. ex rel. Accardi v. Shaughnessy","cite":"347 U.S. 260","y":1954,"id":"1940-1955/347us260","sc":1,"sum":"Petitioner is entitled to an opportunity in thp district court to prove the allegation; and, if he does prove it, he should receive a new hearing before the Board without the burden of previous proscription by the list.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"U.S. ex rel. Vajtauer v. Comm’r of Immigration","cite":"273 U.S. 103","y":1927,"id":"scdb/1926-142","sc":1,"sum":"1. Want of due process in.proceedings for the deportation of an alien is notestablished by showing merely that the decision was erroneous or that incompetent evidence was received and considered. P, 106,","sumSrc":"Headnote (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"United States v. Gue Lim","cite":"176 U.S. 459","y":1900,"id":"scdb/1899-133","sc":1,"sum":"Under the act of July 6, 1884, c. 220, 23 Stat. 115, construed in connection with the treaty with China of November 17, 1880, 22 Stat. 826, the wives and minor children of Chinese merchants domiciled in this country, may enter the United States without certificates.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"22","2":"11"}},{"t":"case","label":"United States v. Reynolds","cite":"345 U.S. 1","y":1953,"id":"1940-1955/345us1","sc":1,"sum":"The court held that cause for privilege must be reasonably demonstrated. As a result, the government may withhold information for reasons of national security even when that information is vital to the plaintiff's case. On remand, the plaintiffs lost.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"United States v. Wong Kim Ark","cite":"169 U.S. 649","y":1898,"id":"1850-1900/169us649","sc":1,"sum":"Because Wong was born in the United States and his parents were not “employed in any diplomatic or official capacity under the Emperor of China,” the Citizenship Clause of the Fourteenth Amendment automatically makes him a U.S. citizen.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Vitek v. Jones","cite":"445 U.S. 480","y":1980,"id":"1979/78-1155","sc":1,"ar":1,"sum":"The judgment is affirmed as modified. Pp. 486-497; 497-500. Affirmed as modified.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Whitmore v. Arkansas","cite":"495 U.S. 149","y":1990,"id":"1989/88-7146","sc":1,"sum":"Whitmore lacks standing to proceed in this Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"Wolff v. McDonnell","cite":"418 U.S. 539","y":1974,"id":"1973/73-679","sc":1,"sum":"The Supreme Court held that while prisoners are not entitled to full due process protections, disciplinary proceedings must include written notice to the defendant of the charges, a written statement of evidence, and the opportunity for an inmate to call witnesses and present evidence.","sumSrc":"Oyez","by":{"1":"26, 27, 42"}},{"t":"case","label":"Wood v. Allen","cite":"558 U.S. 290","y":2010,"id":"2009/08-9156","sc":1,"sum":"The Court held that an inmate's conviction was proper, despite the fact that his attorney failed to properly investigate or introduce evidence that his IQ was well below average.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Yee v. Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"Zyapkov v. Lynch","cite":"817 F.3d 556","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/817/556/","by":{"1":"31"}},{"t":"usc","label":"5 U.S.C. § 559","url":"https://www.law.cornell.edu/uscode/text/5/559","by":{"1":"17"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","subs":["(1)"],"stext":{"head":"§702. Right of review","paras":[[0,"A person suffering legal wrong because of agency action, or adversely affected or aggrieved by agency action within the meaning of a relevant statute, is entitled to judicial review thereof. An action in a court of the United States seeking relief other than money damages and stating a claim that an agency or an officer or employee thereof acted or failed to act in an official capacity or under color of legal authority shall not be dismissed nor relief therein be denied on the ground that it is against the United States or that the United States is an indispensable party. The United States may be named as a defendant in any such action, and a judgment or decree may be entered against the United States: Provided, That any mandatory or injunctive decree shall specify the Federal officer or officers (by name or by title), and their successors in office, personally responsible for compliance. Nothing herein (1) affects other limitations on judicial review or the power or duty of the court to dismiss any action or deny relief on any other appropriate legal or equitable ground; or (2) confers authority to grant relief if any other statute that grants consent to suit expressly or impliedly forbids the relief which is sought."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/702?type=usc&year=mostrecent&link-type=html"},"head":"§702. Right of review","tname":"Government Organization and Employees","by":{"1":"17","2":"4"}},{"t":"usc","label":"8 U.S.C. § 1183a","url":"https://www.law.cornell.edu/uscode/text/8/1183a","subs":["(a)(1)","(a)(1)(B)","(a)(1)(C)","(d)(1)","(d)(2)"],"by":{"1":"5, 28, 5, 28, 31, 5, 5, 5"}},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","subs":["(b)(1)"],"stext":{"head":"§1229b. Cancellation of removal; adjustment of status","paras":[[0,"(a) Cancellation of removal for certain permanent residents"],[0,"The Attorney General may cancel removal in the case of an alien who is inadmissible or deportable from the United States if the alien—"],[1,"(1) has been an alien lawfully admitted for permanent residence for not less than 5 years,"],[1,"(2) has resided in the United States continuously for 7 years after having been admitted in any status, and"],[1,"(3) has not been convicted of any aggravated felony."],[0,"(b) Cancellation of removal and adjustment of status for certain nonpermanent residents"],[0,"(1) In general"],[1,"The Attorney General may cancel removal of, and adjust to the status of an alien lawfully admitted for permanent residence, an alien who is inadmissible or deportable from the United States if the alien—"],[2,"(A) has been physically present in the United States for a continuous period of not less than 10 years immediately preceding the date of such application;"],[2,"(B) has been a person of good moral character during such period;"],[2,"(C) has not been convicted of an offense under section 1182(a)(2), 1227(a)(2), or 1227(a)(3) of this title, subject to paragraph (5); and"],[2,"(D) establishes that removal would result in exceptional and extremely unusual hardship to the alien's spouse, parent, or child, who is a citizen of the United States or an alien lawfully admitted for permanent residence."],[0,"(2) Special rule for battered spouse or child"],[0,"(A) Authority"],[2,"The Attorney General may cancel removal of, and adjust to the status of an alien lawfully admitted for permanent residence, an alien who is inadmissible or deportable from the United States if the alien demonstrates that—"],[3,"(i)(I) the alien has been battered or subjected to extreme cruelty by a spouse or parent who is or was a United States citizen (or is the parent of a child of a United States citizen and the child has been battered or subjected to extreme cruelty by such citizen parent);"],[3,"(II) the alien has been battered or subjected to extreme cruelty by a spouse or parent who is or was a lawful permanent resident (or is the parent of a child of an alien who is or was a lawful permanent resident and the child has been battered or subjected to extreme cruelty by such permanent resident parent); or"],[3,"(III) the alien has been battered or subjected to extreme cruelty by a United States citizen or lawful permanent resident whom the alien intended to marry, but whose marriage is not legitimate because of that United States citizen's or lawful permanent resident's bigamy;"],[3,"(ii) the alien has been physically present in the United States for a continuous period of not less than 3 years immediately preceding the date of such application, and the issuance of a charging document for removal proceedings shall not toll the 3-year period of continuous physical presence in the United States;"],[3,"(iii) the alien has been a person of good moral character during such period, subject to the provisions of subparagraph (C);"],[3,"(iv) the alien is not inadmissible under paragraph (2) or (3) of section 1182(a) of this title, is not deportable under paragraphs (1)(G) or (2) through (4) of section 1227(a) of this title, subject to paragraph (5), and has not been convicted of an aggravated felony; and"],[3,"(v) the removal would result in extreme hardship to the alien, the alien's child, or the alien's parent."],[0,"(B) Physical presence"],[2,"Notwithstanding subsection (d)(2), for purposes of subparagraph (A)(ii) or for purposes of section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996), an alien shall not be considered to have failed to maintain continuous physical presence by reason of an absence if the alien demonstrates a connection between the absence and the battering or extreme cruelty perpetrated against the alien. No absence or portion of an absence connected to the battering or extreme cruelty shall count toward the 90-day or 180-day limits established in subsection (d)(2). If any absence or aggregate absences exceed 180 days, the absences or portions of the absences will not be considered to break the period of continuous presence. Any such period of time excluded from the 180-day limit shall be excluded in computing the time during which the alien has been physically present for purposes of the 3-year requirement set forth in this subparagraph, subparagraph (A)(ii), and section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996)."],[0,"(C) Good moral character"],[2,"Notwithstanding section 1101(f) of this title, an act or conviction that does not bar the Attorney General from granting relief under this paragraph by reason of subparagraph (A)(iv) shall not bar the Attorney General from finding the alien to be of good moral character under subparagraph (A)(iii) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996), if the Attorney General finds that the act or conviction was connected to the alien's having been battered or subjected to extreme cruelty and determines that a waiver is otherwise warranted."],[0,"(D) Credible evidence considered"],[2,"In acting on applications under this paragraph, the Attorney General shall consider any credible evidence relevant to the application. The determination of what evidence is credible and the weight to be given that evidence shall be within the sole discretion of the Attorney General."],[0,"(3) Recordation of date"],[1,"With respect to aliens who the Attorney General adjusts to the status of an alien lawfully admitted for permanent residence under paragraph (1) or (2), the Attorney General shall record the alien's lawful admission for permanent residence as of the date of the Attorney General's cancellation of removal under paragraph (1) or (2)."],[0,"(4) Children of battered aliens and parents of battered alien children"],[0,"(A) In general"],[2,"The Attorney General shall grant parole under section 1182(d)(5) of this title to any alien who is a—"],[3,"(i) child of an alien granted relief under section 1229b(b)(2) or 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996); or"],[3,"(ii) parent of a child alien granted relief under section 1229b(b)(2) or 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996)."],[0,"(B) Duration of parole"],[2,"The grant of parole shall extend from the time of the grant of relief under subsection (b)(2) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996) to the time the application for adjustment of status filed by aliens covered under this paragraph has been finally adjudicated. Applications for adjustment of status filed by aliens covered under this paragraph shall be treated as if the applicants were VAWA self-petitioners. Failure by the alien granted relief under subsection (b)(2) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996) to exercise due diligence in filing a visa petition on behalf of an alien described in clause (i) or (ii) may result in revocation of parole."],[0,"(5) Application of domestic violence waiver authority"],[1,"The authority provided under section 1227(a)(7) of this title may apply under paragraphs (1)(B), (1)(C), and (2)(A)(iv) in a cancellation of removal and adjustment of status proceeding."],[0,"(6) Relatives of trafficking victims"],[0,"(A) In general"],[2,"Upon written request by a law enforcement official, the Secretary of Homeland Security may parole under section 1182(d)(5) of this title any alien who is a relative of an alien granted continued presence under section 7105(c)(3)(A) of title 22, if the relative—"],[3,"(i) was, on the date on which law enforcement applied for such continued presence—"],[4,"(I) in the case of an alien granted continued presence who is under 21 years of age, the spouse, child, parent, or unmarried sibling under 18 years of age, of the alien; or"],[4,"(II) in the case of an alien granted continued presence who is 21 years of age or older, the spouse or child of the alien; or"],[3,"(ii) is a parent or sibling of the alien who the requesting law enforcement official, in consultation with the Secretary of Homeland Security, as appropriate, determines to be in present danger of retaliation as a result of the alien's escape from the severe form of trafficking or cooperation with law enforcement, irrespective of age."],[0,"(B) Duration of parole"],[0,"(i) In general"],[3,"The Secretary may extend the parole granted under subparagraph (A) until the final adjudication of the application filed by the principal alien under section 1101(a)(15)(T)(ii) of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1229b?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1229b. Cancellation of removal; adjustment of status","tname":"Aliens and Nationality","by":{"1":"4"}},{"t":"usc","label":"8 U.S.C. § 1325","url":"https://www.law.cornell.edu/uscode/text/8/1325","subs":["(c)"],"by":{"1":"31"}},{"t":"usc","label":"8 U.S.C. § 1534","url":"https://www.law.cornell.edu/uscode/text/8/1534","subs":["(e)(3)(B)"],"by":{"1":"45"}},{"t":"usc","label":"18 U.S.C. § 1546","url":"https://www.law.cornell.edu/uscode/text/18/1546","by":{"1":"31"}},{"t":"usc","label":"31 U.S.C. § 9701","url":"https://www.law.cornell.edu/uscode/text/31/9701","by":{"1":"44"}},{"t":"law","label":"Pub. L. No. 82-414","url":"https://www.govinfo.gov/link/statute/66/163","by":{"1":"24"}},{"t":"reg","label":"8 C.F.R. § 103.2","url":"https://www.ecfr.gov/current/title-8/section-103.2","subs":["(a)","(b)","(b)(6)","(b)(16)"],"by":{"1":"30, 3, 30, 44, 46"}},{"t":"reg","label":"8 C.F.R. § 205.1","url":"https://www.ecfr.gov/current/title-8/section-205.1","subs":["(a)(3)"],"by":{"1":"32"}},{"t":"reg","label":"8 C.F.R. § 212.7","url":"https://www.ecfr.gov/current/title-8/section-212.7","subs":["(e)(14)(i)"],"by":{"1":"4, 27"}},{"t":"reg","label":"22 C.F.R. § 40.6","url":"https://www.ecfr.gov/current/title-22/section-40.6","by":{"1":"40, 41"}},{"t":"reg","label":"22 C.F.R. § 42.43","url":"https://www.ecfr.gov/current/title-22/section-42.43","subs":["(a)"],"by":{"1":"31"}},{"t":"reg","label":"22 C.F.R. § 42.81","url":"https://www.ecfr.gov/current/title-22/section-42.81","subs":["(b)","(e)"],"by":{"1":"29, 47, 6, 29, 38, 41, 43, 47"}},{"t":"reg","label":"Provisional Unlawful Presence Waivers of Inadmissibility for Certain Immediate Relatives, 78 Fed. Reg. 536","url":"https://www.govinfo.gov/link/fr/78/536","by":{"1":"4, 27","2":"8"}},{"t":"reg","label":"Expansion of Provisional Unlawful Presence Waivers of Inadmissibility, 81 Fed. Reg. 50244","url":"https://www.govinfo.gov/link/fr/81/50244","by":{"1":"4, 5","2":"8"}},{"t":"reg","label":"Schedule of Fees for Consular Services, 86 Fed. Reg. 74018","url":"https://www.govinfo.gov/link/fr/86/74018","by":{"1":"44"}},{"t":"case","label":"Allen v. Milas","cite":"896 F.3d 1094","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/896/1094/","by":{"2":"4"}},{"t":"case","label":"Baldwin v. Reese","cite":"541 U.S. 27","y":2004,"id":"2003/02-964","sc":1,"sum":"The Court held that Reese did not \"fairly present\" his Sixth Amendment ineffective counsel claim to state courts. Federal law thus barred Reese from turning to federal courts. The state court could have understood Reese's claims were federal if the court had read the lower court opinion.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Block v. Community Nutrition Inst.","cite":"467 U.S. 340","y":1984,"id":"1983/83-458","sc":1,"sum":"The individual consumers may not obtain judicial review of the milk market orders in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"Meachum v. Fano","cite":"427 U.S. 215","y":1976,"id":"1975/75-252","sc":1,"sum":"The Due Process Clause of the Fourteenth Amendment held not to entitle a duly convicted state prisoner to a factfinding hearing when he is transferred to a prison the conditions of which are substantially less favorable to him, absent a state law or practice conditioning such transfers on proof of serious misconduct or the occurrence of other specified events. Such a transfer does not infringe or implicate a …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12, 13"}},{"t":"case","label":"Orloff v. Willoughby","cite":"345 U.S. 83","y":1953,"id":"scdb/1952-059","sc":1,"sum":"Petitioner, a physician educated at government expense and beyond the usual draft age, was inducted into the Army under the Doctors' Draft Law, 50 U. S. C. App. § 454 (i), which authorizes special conscription of certain \"medical and allied specialist categories.\" Because of his refusal, on grounds of possible selfincrimination, to state in connection with his application for a commission whether he was or hact been …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"23"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)(1)"],"by":{"2":"4, 4"}},{"t":"usc","label":"8 U.S.C. § 1152","url":"https://www.law.cornell.edu/uscode/text/8/1152","subs":["(a)(4)"],"by":{"2":"14"}},{"t":"reg","label":"3 C.F.R. pt. 720","url":"https://www.ecfr.gov/current/title-3/part-720","by":{"2":"21"}}]};